/** All translations for zizhitongjian ch.042 — Garrett M. Petersen (2026), Composer 2.5 */
export const entries = [
  { zh: "【漢紀三十四】起上章攝提格，盡旃蒙協洽，凡六年。", literal: "【Han Records 34】 From Shangzhang Shetige through Zhanmeng Xieqia—in all, six years.", idiomatic: "【Han Records 34】 From the first year of the Shangzhang cycle through the last year of the Zhanmeng cycle—six years in all." },
  { zh: "世祖光武皇帝中之上", literal: "Founding Emperor Guangwu, Middle Part, Upper Section.", idiomatic: "The Founding Emperor Guangwu — Middle Part, Upper Section." },
  { zh: "1春，正月，丙辰，以舂陵鄉為章陵縣，世世復傜役，比豐、沛。", literal: "1. In spring, the first month, on the day bingchen, Chunling township was made Zhangling county; corvée and levies were remitted for all generations, on a par with Feng and Pei.", idiomatic: "1. In spring, in the first month, on the day bingchen, Chunling township was made Zhangling county, with corvée and levies remitted for all generations, as at Feng and Pei." },
  { zh: "2吳漢等拔朐，斬董憲、龐萌，江、淮、山東悉平。", literal: "2. Wu Han and others took Ju, beheaded Dong Xian and Pang Meng; the Yangtze, Huai, and Shandong were all pacified.", idiomatic: "2. Wu Han and others captured Ju and beheaded Dong Xian and Pang Meng; the lands along the Yangtze, the Huai, and Shandong were all pacified." },
  { zh: "諸將還京師，置酒賞賜。", literal: "The generals returned to the capital; wine was set out and rewards given.", idiomatic: "The generals returned to the capital, where the emperor feasted them and gave rewards." },
  { zh: "帝積苦兵間，以隗囂遣子內侍，公孫述遠據邊垂，乃謂諸將曰：「且當置此兩子於度外耳。", literal: "The emperor, long wearied amid warfare, because Wei Xiao had sent his son in as attendant and Gongsun Shu held the far borderlands, thereupon said to the generals: \"For now we ought to set these two fellows outside our reckoning.\"", idiomatic: "The emperor, worn down by years of war, noted that Wei Xiao had sent his son as a hostage and that Gongsun Shu held the distant marches. He told his generals, \"For now let us set these two aside.\"" },
  { zh: "」因休諸將於雒陽，分軍士於河內，數騰書隴、蜀，告示禍福。", literal: "\" Thereupon he rested the generals at Luoyang, distributed troops to Henei, and repeatedly sent letters flying to Long and Shu, proclaiming fortune and ruin.", idiomatic: "\" He gave his generals rest at Luoyang, posted troops in Henei, and again and again sent letters to Long and Shu proclaiming blessing and doom." },
  { zh: "公孫述屢移書中國，自陳符命，冀以惑眾。", literal: "Gongsun Shu repeatedly sent letters to the central lands, himself presenting his mandate from omens, hoping thereby to delude the multitude.", idiomatic: "Gongsun Shu sent letter after letter to the central court, citing omens of his destined rule, hoping to sway men's minds." },
  { zh: "帝與述書曰：「圖讖言公孫，即宣帝也。", literal: "The emperor wrote to Shu: \"The charts and prophecies speak of 'Gongsun'—that means Emperor Xuan.\"", idiomatic: "The emperor wrote to Gongsun Shu: \"The prophecies speak of 'Gongsun'—they mean Emperor Xuan.\"" },
  { zh: "代漢者姓當塗，其名高；", literal: "\"He who replaces Han bears the surname Dangtu; his given name is Gao;\"", idiomatic: "\"'He who replaces Han bears the surname Dangtu; his given name is Gao;'—\"" },
  { zh: "君豈高之身邪！", literal: "\"are you perhaps Gao in person!\"", idiomatic: "\"are you that Gao in person?\"" },
  { zh: "乃復以掌文為瑞，王莽何足效乎！", literal: "\"Yet you again take palm-script as an auspice—how is Wang Mang worth imitating!\"", idiomatic: "\"Yet you again take palm-writing as a portent—Wang Mang is hardly worth imitating!\"" },
  { zh: "君非吾賊臣亂子，倉卒時人皆欲為君事耳。", literal: "\"You are not my rebel minister or disorderly son; in the rush of the moment everyone wished to serve you.\"", idiomatic: "\"You are no rebel of mine; in the chaos everyone wished to serve you for a time.\"" },
  { zh: "君日月已逝，妻子弱小，當早為定計。", literal: "\"Your sun and moon have already set; wife and children are young and weak—you ought early to settle your plan.\"", idiomatic: "\"Your day is passing; your wife and children are young and weak. Settle your course soon.\"" },
  { zh: "天下神器，不可力爭，宜留三思！", literal: "\"The sacred vessel of the realm cannot be seized by force—leave room for three thoughts!\"", idiomatic: "\"The Mandate is not won by force alone—think thrice before you act!\"" },
  { zh: "」署曰「公孫皇帝」。", literal: "\" The superscription read \"Emperor Gongsun.\"", idiomatic: "\" He addressed it to \"Emperor Gongsun.\"" },
  { zh: "述不答。", literal: "Shu did not reply.", idiomatic: "Gongsun Shu did not answer." },
  { zh: "其騎都尉平陵荊邯說述曰：「漢高祖起於行陳之中，兵破身困者數矣；", literal: "His Cavalry Commandant Jing Han of Pingling urged Shu: \"Han Gaozu rose from the ranks of the marching camp; his army was broken and his person distressed many times;\"", idiomatic: "His Cavalry Commandant Jing Han of Pingling urged Gongsun Shu: \"Han Gaozu rose from the ranks; his armies were shattered and he himself brought low again and again;\"" },
  { zh: "然軍敗復合，瘡愈復戰。", literal: "\"yet when the army was defeated it gathered again; when wounds healed he fought again.\"", idiomatic: "\"yet when his army broke it re-formed; when his wounds healed he fought again.\"" },
  { zh: "何則？", literal: "\"Why?\"", idiomatic: "\"Why?\"" },
  { zh: "前死而成功，愈於卻就於滅亡也！", literal: "\"To die forward yet succeed is better than to retreat toward destruction!\"", idiomatic: "\"To press on even unto death and win is better than to fall back toward ruin!\"" },
  { zh: "隗囂遭遇運會，割有雍州，兵強士附，威加山東；", literal: "\"Wei Xiao met with the turning of fortune, carved out Yong Province, had strong soldiers and attached warriors, and his prestige reached beyond the mountains east;", idiomatic: "\"Wei Xiao seized his moment, held Yong Province, commanded strong armies and loyal men, and his fame reached east of the passes;\"" },
  { zh: "遇更始政亂，復失天下，眾庶引領，四方瓦解，囂不及此時推危乘勝以爭天命，而退欲為西伯之事，尊師章句，賓友處士，偃武息戈，卑辭事漢，喟然自以文王復出也！", literal: "\"when Gengshi's government fell into disorder he again lost the realm; the common folk craned their necks and the four quarters crumbled—yet Xiao did not at this time press the peril and ride victory to contend for Heaven's mandate, but withdrew wishing to play the Western Earl: honoring teachers and classical lines, keeping guest-friends and recluses, laying down arms and resting spears, with humble words serving Han, sighing to himself that King Wen had come again!\"", idiomatic: "\"when the Gengshi court collapsed he might have taken the realm—the people looked to him and the empire fell apart—yet he did not press his advantage and contend for the Mandate. Instead he played King Wen: honoring teachers and classical glosses, gathering scholars and recluses, laying down arms, humbling himself before Han, sighing that King Wen had returned!\"" },
  { zh: "令漢帝釋關、隴之憂，專精東伐，四分天下而有其三；", literal: "\"This let the Han emperor release his cares for the passes and Long, concentrate on eastern campaigns, and hold three parts of a realm quartered;", idiomatic: "\"So the Han emperor left the passes and Long untroubled, turned east, and held three quarters of the realm;\"" },
  { zh: "發間使，召攜貳，使西州豪傑咸居心於山東，則五分而有其四；", literal: "\"send secret envoys, summon the hesitant and divided, and make the great men of the western provinces all set their hearts on the east—then of five parts he would hold four;", idiomatic: "\"send secret agents, win over the wavering, and turn the western chieftains' hearts toward the east—then four parts in five would be his;\"" },
  { zh: "若舉兵天水，必至沮潰，天水既定，則九分而有其八。", literal: "\"if he raised troops at Tianshui they would surely break and flee; once Tianshui was settled, then of nine parts he would hold eight.\"", idiomatic: "\"if he marched on Tianshui the enemy would break; with Tianshui secure, eight parts in nine would be his.\"" },
  { zh: "陛下以梁州之地，內奉萬乘，外給三軍，百姓愁困，不堪上命，將有王氏自潰之變矣！", literal: "\"Your Majesty, with Liang Province's lands, within supplying the imperial carriage and without provisioning the Three Armies—the common people are bitter and distressed, unable to bear commands from above; there will be a Wang Mang-style collapse from within!\"", idiomatic: "\"Your Majesty holds Liang Province, supplying the throne within and the armies without, while the people groan under your demands—they cannot bear it. You will face a Wang Mang-style collapse from within!\"" },
  { zh: "臣之愚計，以為宜及天下之望未絕，豪桀尚可招誘，急以此時發國內精兵，令田戎據江陵，臨江南之會，倚巫山之固，築壘堅守，傳檄吳、楚，長沙以南必隨風而靡。", literal: "\"This servant's foolish plan holds that you ought, while the realm's hopes are not yet spent and bold men can still be enticed, urgently at this time send out the realm's elite troops, order Tian Rong to hold Jiangling, face the junction of the south of the Yangtze, lean on Wushan's strength, build ramparts and hold firm, send proclamations to Wu and Chu—the lands south of Changsha will surely bend like grass in the wind.\"", idiomatic: "\"My counsel: while hope in you still lives and heroes may yet be won, strike now with your best troops. Put Tian Rong at Jiangling above the Yangtze junction, behind Wushan's ramparts, and hold fast. Send proclamations to Wu and Chu—the lands south of Changsha will bow like reeds in wind.\"" },
  { zh: "令延岑出漢中，定三輔，天水、隴西拱手自服。", literal: "\"Order Yan Cen out from Hanzhong to settle the Three Metropolises; Tianshui and Longxi will fold their hands and submit of themselves.\"", idiomatic: "\"Send Yan Cen from Hanzhong to secure the Three Metropolises; Tianshui and Longxi will surrender without a fight.\"" },
  { zh: "如此，海內震搖，冀有大利。", literal: "\"Thus the realm within the seas would shake; we might hope for great gain.\"", idiomatic: "\"Then the empire would tremble—and great profit might follow.\"" },
  { zh: "」述以問群臣，博士吳柱曰：「武王伐殷，八百諸侯不期同辭，然猶還師以待天命。", literal: "\" Shu put the question to his ministers; the Erudite Wu Zhu said: \"King Wu attacked Yin: eight hundred lords came together unbidden in one voice, yet he still turned the army back to await Heaven's mandate.\"", idiomatic: "\" Gongsun Shu asked his ministers. Erudite Wu Zhu said, \"When King Wu attacked Yin, eight hundred lords came of one accord—yet he still withdrew his army to await Heaven's mandate.\"" },
  { zh: "未聞無左右之助。", literal: "\"One has not heard of lacking help at one's side\"", idiomatic: "\"No one has marched far without allies at hand\"" },
  { zh: "而欲出師千里之外者也。", literal: "\"yet wishing to send the army out a thousand li.\"", idiomatic: "\"yet wishing to march a thousand li beyond your borders.\"" },
  { zh: "」邯曰：「今東帝無尺十之柄，驅烏合之眾，跨馬陷敵，所向輒平，不亟乘時與之分功，而坐談武王之說，是復效隗囂欲為西伯也。", literal: "\" Han said: \"Now the eastern emperor lacks even a foot of ten in authority; he drives a flock of crows gathered, spurs his horse and breaks the enemy—where he turns all is soon level. If we do not urgently seize the time and share in his merit, but sit and discourse on King Wu's example, this is again to imitate Wei Xiao wishing to be the Western Earl.\"", idiomatic: "\" Jing Han said, \"The eastern emperor holds barely a finger's breadth of power. He drives a rabble, spurs his horse into the fray, and wins wherever he turns. If we do not seize this moment and share his conquests, but sit citing King Wu, we repeat Wei Xiao playing King Wen.\"" },
  { zh: "述然邯言，欲悉發北軍屯士及山東客兵，使延岑、田戎分出兩道，與漢中諸將合兵並勢。", literal: "Shu approved Han's words and wished to send out all northern-army garrison troops and eastern guest-soldiers, ordering Yan Cen and Tian Rong to divide into two routes and join the Hanzhong generals in combined force.", idiomatic: "Gongsun Shu agreed with Jing Han and planned to mobilize every northern garrison soldier and eastern mercenary, sending Yan Cen and Tian Rong by two routes to join the Hanzhong commanders in one thrust." },
  { zh: "蜀人及其弟光以為不宜空國千里之外，決成敗於一舉，固爭之，述乃止。", literal: "Shu people and his younger brother Guang held that one ought not to empty the state a thousand li away and decide success or failure in a single throw; they firmly contested it, and Shu thereupon stopped.", idiomatic: "The people of Shu and his brother Guang argued that he must not strip the realm and stake everything on one throw a thousand li away. They pressed him hard, and he desisted." },
  { zh: "延岑、田戎亦數請兵立功，述終疑不聽，唯公孫氏得任事。", literal: "Yan Cen and Tian Rong also repeatedly begged troops to win merit; Shu to the end was suspicious and would not listen—only the house of Gongsun received appointments.", idiomatic: "Yan Cen and Tian Rong also begged again and again for troops to earn glory, but Gongsun Shu remained suspicious and refused. Only his own clan held office." },
  { zh: "述廢銅錢，置鐵錢，貨幣不行，百姓苦之。", literal: "Shu abolished copper cash and instituted iron money; currency did not circulate and the common people suffered from it.", idiomatic: "Gongsun Shu abolished copper coin and issued iron money. Trade stalled and the people groaned under it." },
  { zh: "為政苛細，察於小事，如為清水令時而已。", literal: "In government he was harsh and minute, scrutinizing small matters—just as when he had been magistrate of Qingshui.", idiomatic: "His rule was petty and exacting, obsessed with trifles—as when he had been magistrate of Qingshui." },
  { zh: "好改易郡縣官名。", literal: "He loved to change the official names of commanderies and counties.", idiomatic: "He loved to rename commanderies and counties." },
  { zh: "少嘗為郎，習漢家故事，出入法駕，鸞旗旄騎。", literal: "In youth he had once been a gentleman-attendant, versed in Han household precedents; going out and in he used the statutory imperial equipage—phoenix banners and pennoned horsemen.", idiomatic: "As a youth he had served as a court gentleman and knew Han ritual. He went abroad with imperial pomp—phoenix banners and pennoned escorts." },
  { zh: "又立其兩子為王，食犍為、廣漢各數縣。", literal: "He also established his two sons as kings, with fiefs of several counties each in Qianwei and Guanghan.", idiomatic: "He also made his two sons kings, enfeoffing them with several counties each in Qianwei and Guanghan." },
  { zh: "或諫曰：「成敗未可知，戎士暴露而先王愛子，示無大志也！", literal: "Someone remonstrated: \"Success or failure is not yet known; war-fighters are exposed to the elements while beloved sons are made kings first—this shows no great ambition!\"", idiomatic: "Someone urged him: \"Victory is not yet certain. Your soldiers freeze in the field while you crown your sons—this shows small ambition!\"" },
  { zh: "」述不從，由此大臣皆怨。", literal: "\" Shu would not follow; from this the great ministers all resented.", idiomatic: "\" He would not listen, and from that his ministers turned against him." },
  { zh: "3馮異自長安入朝，帝謂公卿曰：「是我起兵時主簿也，為吾披荊棘，定關中。", literal: "3. Feng Yi came from Chang'an to audience; the emperor said to the excellencies and ministers: \"This was my registrar when I first raised troops; for me he cut through brambles and settled Guanzhong.\"", idiomatic: "3. Feng Yi came from Chang'an to court. The emperor told the ministers, \"This was my registrar when I first raised arms. He cut through the thorns for me and secured Guanzhong.\"" },
  { zh: "」既罷，賜珍寶、錢帛，詔曰：「倉卒蕪蔞亭豆粥，虖沱河麥飯，厚意久不報。", literal: "\" When dismissed, he was granted treasures, cash, and silks; an edict said: \"In haste at Wulou Pavilion, bean porridge; at Hutuo River, wheat meal—your deep kindness long unrewarded.\"", idiomatic: "\" When the audience ended he gave him treasures, cash, and silk, with an edict: \"Bean porridge at Wulou Pavilion, wheat gruel at Hutuo River—your kindness went long unrewarded.\"" },
  { zh: "」異稽首謝曰：「臣聞管仲謂桓公曰：『願君無忘射鉤，臣無忘檻車。", literal: "\" Yi knocked his head and thanked him, saying: \"Your servant has heard that Guan Zhong told Duke Huan: 'May my lord not forget the arrow that hooked him; may your servant not forget the caged cart.\"", idiomatic: "\" Feng Yi kowtowed and said, \"I have heard that Guan Zhong told Duke Huan of Qi: 'May my lord not forget the arrow that hooked you; may I not forget the prison cart.'\"" },
  { zh: "』齊國賴之。", literal: "\"' Qi relied on this.\"", idiomatic: "\"' On that Qi stood.\"" },
  { zh: "臣今亦願國家無忘河北之難，小臣不敢忘巾車之恩。", literal: "\"Your servant now also wishes the state not to forget the hardships north of the river; this petty servant dares not forget the kindness of the covered cart.\"", idiomatic: "\"I too pray the realm will not forget the trials north of the river; I dare not forget the kindness of the covered cart.\"" },
  { zh: "」留十餘日，令與妻子還西。", literal: "\" He was kept more than ten days, then ordered with wife and children to return west.", idiomatic: "\" He stayed more than ten days, then was sent west with his wife and children." },
  { zh: "4申屠剛、杜林自隗囂所來，帝皆拜侍御史。", literal: "4. Shentu Gang and Du Lin came from Wei Xiao's domain; the emperor invested both as Attendant Censors.", idiomatic: "4. Shentu Gang and Du Lin came from Wei Xiao's camp; the emperor made both Attendant Censors." },
  { zh: "以鄭興為太中大夫。", literal: "Zheng Xing was made Grand Palace Grandee.", idiomatic: "Zheng Xing was appointed Grand Palace Grandee." },
  { zh: "5三月，公孫述使田戎出江關，招其故眾，欲以取荊州，不克。", literal: "5. In the third month, Gongsun Shu sent Tian Rong out through the Yangtze passes to summon his former followers, intending thereby to take Jing Province; he did not succeed.", idiomatic: "5. In the third month Gongsun Shu sent Tian Rong through the river passes to rally his old followers and seize Jing Province. He failed." },
  { zh: "帝乃詔隗囂，欲從天水伐蜀。", literal: "The emperor thereupon issued an edict to Wei Xiao, wishing to march on Shu from Tianshui.", idiomatic: "The emperor then ordered Wei Xiao to join an invasion of Shu from Tianshui." },
  { zh: "囂上言：「白水險阻，棧閣敗絕。", literal: "Xiao memorialized upward: \"Bai River is perilous and blocked; plank roads and passes are ruined and cut off.\"", idiomatic: "Wei Xiao replied: \"The Bai River country is rugged; the plank roads are broken and impassable.\"" },
  { zh: "述性嚴酷，上下相患，須其罪惡孰著而攻之，此大呼響應之勢也。", literal: "\"Shu's nature is harsh and cruel; above and below mistrust one another—we must wait until his crimes are fully manifest and then attack; this is the momentum of a great shout answered in echo.\"", idiomatic: "\"Gongsun Shu is harsh and cruel; his court and people fear one another. Wait until his crimes are plain, then strike—the realm will answer like an echo to a shout.\"" },
  { zh: "」帝知其終不為用，乃謀討之。", literal: "\" The emperor knew he would in the end not be employed and thereupon plotted to strike him down.", idiomatic: "\" The emperor knew Wei Xiao would never serve him and began planning his destruction." },
  { zh: "6夏，四月，丙子，上行幸長安，謁園陵；", literal: "6. In summer, the fourth month, on the day bingzi, the emperor traveled in person to Chang'an and visited the park tombs;", idiomatic: "6. In summer, in the fourth month, on the day bingzi, the emperor went in person to Chang'an and visited the imperial tombs;" },
  { zh: "遣耿弇、蓋延等七將軍從隴道伐蜀，先使中郎將來歙奉璽書賜囂諭旨。", literal: "he sent the seven generals Geng Yan, Gai Yan, and others by the Long road to attack Shu, first dispatching the Palace Gentleman Lai Xi to bear the imperial-seal letter granting Xiao the edict's purport.", idiomatic: "he sent Geng Yan, Gai Yan, and five other generals against Shu by the Long road, and first dispatched Palace Gentleman Lai Xi with an imperial letter to instruct Wei Xiao." },
  { zh: "囂復多設疑故，事久冘豫不決。", literal: "Xiao again set up many doubts and pretexts; the matter dragged on long, dilatory and undecided.", idiomatic: "Wei Xiao raised objection after objection; days passed and he still would not decide." },
  { zh: "歙遂發憤質素囂曰：「國家以君知臧否，曉廢興，故以手書暢意。", literal: "Xi thereupon flared in anger and confronted Xiao plainly: \"The state, because you know good from ill and understand decline and rise, therefore sent a personal letter to express its intent fully.\"", idiomatic: "Lai Xi then burst out and confronted Wei Xiao: \"The throne believes you know good from evil and rise from fall—that is why it sent you this personal letter.\"" },
  { zh: "足下推忠誠，既遣伯春委質，而反欲用佞惑之言，為族滅之計邪！", literal: "\"You, sir, have professed loyalty and already sent Bochun as hostage—yet you turn back wishing to use flatterers' deluding words and make a plan for extermination of your clan!\"", idiomatic: "\"You pledged loyalty and sent your son Bochun as hostage—will you now heed flatterers and plot your clan's destruction?\"" },
  { zh: "」因欲前刺囂。", literal: "\" He thereupon wished to step forward and stab Xiao.", idiomatic: "\" He started forward to stab Wei Xiao." },
  { zh: "囂起入，部勒兵將殺歙，歙徐杖節就車而去，囂使牛邯將兵圍守之。", literal: "Xiao rose and went inside, mustered troops intending to kill Xi; Xi slowly, staff and credentials in hand, went to his carriage and left; Xiao sent Niu Han to lead troops to surround and hold him.", idiomatic: "Wei Xiao rose and withdrew, called up troops to kill him. Lai Xi walked slowly, staff and credentials in hand, to his carriage and departed. Wei Xiao sent Niu Han to surround and detain him." },
  { zh: "囂將王遵諫曰：「君叔雖單車遠使，而陛下之外兄也，殺之無損於漢，而隨以族滅。", literal: "Xiao's general Wang Zun remonstrated: \"Junshu, though he came on a lone carriage as envoy far away, is nonetheless Your Majesty's maternal cousin; to kill him would not harm Han, but destruction of the clan would follow at once.\"", idiomatic: "Wei Xiao's general Wang Zun urged: \"Lai Xi came alone on a distant mission, but he is the emperor's cousin by marriage. Killing him would not hurt Han—but your clan would perish for it.\"" },
  { zh: "昔宋執楚使，遂有析骸易子之禍。", literal: "\"In former times Song seized Chu's envoy, and thereupon came the calamity of splitting bones and exchanging children.\"", idiomatic: "\"When Song seized Chu's envoy, fathers and sons starved until they bartered flesh.\"" },
  { zh: "小國猶不可辱，況於萬乘之主，重以伯春之命哉！", literal: "\"A small state still may not be insulted—how much less a lord of ten thousand chariots, with Bochun's charge added!\"", idiomatic: "\"Even a small state must not be shamed—how much less an emperor, and with your son Bochun's life at stake!\"" },
  { zh: "」歙為人有信義，言行不違，及往來遊說，皆可按覆；", literal: "\" Xi as a man had trust and righteousness; words and deeds did not diverge; in coming and going to persuade, all could be checked and verified;", idiomatic: "\" Lai Xi was a man of trust; his words matched his deeds, and every embassy he had made could be verified;" },
  { zh: "西州士大夫皆信重之，多為其言，故得免而東歸。", literal: "the gentlemen and grandees of the western provinces all trusted and honored him; many spoke for him—therefore he was spared and returned east.", idiomatic: "the western gentry all trusted him, and many spoke for him, so he was spared and sent east." },
  { zh: "五月，己未，車駕至自長安。", literal: "In the fifth month, on the day jiwei, the imperial carriage returned from Chang'an.", idiomatic: "In the fifth month, on the day jiwei, the emperor returned from Chang'an." },
  { zh: "隗囂遂發兵反，使王元據隴坻，伐木塞道。", literal: "Wei Xiao thereupon raised troops in rebellion, sent Wang Yuan to hold Longzhi, felled trees and blocked the roads.", idiomatic: "Wei Xiao then rebelled, posted Wang Yuan at Longzhi, felled trees and blocked the roads." },
  { zh: "諸將因與囂戰，大敗，各引兵下隴；", literal: "The generals thereupon fought Xiao and were utterly defeated; each led his troops down from Long;", idiomatic: "The generals fought him and were routed; each led his army down from the Long plateau;" },
  { zh: "囂追之急，馬武選精騎為後拒，殺數千人，諸軍乃得還。", literal: "Xiao pressed the pursuit hotly; Ma Wu selected elite horsemen as rear guard, killed several thousand, and the armies thereupon were able to return.", idiomatic: "Wei Xiao pressed hard. Ma Wu chose elite cavalry as rearguard, slew several thousand, and the armies escaped." },
  { zh: "7六月辛卯，詔曰：「夫張官置吏，所以為民也。", literal: "7. On the day xinmao in the sixth month, an edict said: \"To spread offices and set clerks is for the sake of the people.\"", idiomatic: "7. On xinmao day in the sixth month an edict ran: \"Offices exist for the people's sake.\"" },
  { zh: "今百姓遭難，戶口耗少，而縣官吏職，所置尚繁。", literal: "\"Now the people suffer calamity; households and population are depleted and few, yet county official posts set remain still numerous.\"", idiomatic: "\"The people have suffered war; households are few, yet county posts remain too many.\"" },
  { zh: "其令司隸、州牧各實所部，省減吏員，縣國不足置長吏者並之。", literal: "\"Let the Director of the Capital and the provincial governors each verify their jurisdictions, reduce and cut official posts, and merge counties and kingdoms that cannot support chief clerks.\"", idiomatic: "\"Let the Director of the Capital and the provincial governors audit their domains, cut posts, and merge counties too small to need their own magistrates.\"" },
  { zh: "」於是並省四百餘縣，吏職減損，十置其一。", literal: "\" Thereupon more than four hundred counties were merged and cut; official posts were reduced—one set where ten had stood.", idiomatic: "\" More than four hundred counties were merged; posts were cut to one in ten." },
  { zh: "8〔秋〕，九月<ref>〔秋〕九月據《通鑑》通例補「秋」字。", literal: "8. 〔Autumn〕, the ninth month<ref>〔Autumn〕—the character \"autumn\" for the ninth month is supplied per the Comprehensive Mirror's usual practice.", idiomatic: "8. 〔Autumn〕, the ninth month<ref>〔Autumn〕—\"autumn\" is supplied for the ninth month per the Comprehensive Mirror's usual practice." },
  { zh: "</ref>，丙寅晦，日有食之。", literal: "</ref> On the last day of the cycle bingyin, there was a solar eclipse.", idiomatic: "</ref> On the last day of the cycle bingyin there was a solar eclipse." },
  { zh: "執金吾朱浮上疏曰：「昔堯、舜之盛，猶如三考；", literal: "The Commandant of Justice Zhu Fu submitted a memorial: \"In former times, even in the flourishing of Yao and Shun, there was still the three examinations;", idiomatic: "Commandant of Justice Zhu Fu memorialized: \"Even Yao and Shun at their height required three years of trial;\"" },
  { zh: "大漢之興，亦累功效，吏皆積久，至長子孫。", literal: "\"the great Han's rise also accumulated merit through many terms; clerks all served long, until sons and grandsons succeeded.\"", idiomatic: "\"Han too rose through long service; officers held office for years until sons and grandsons inherited their posts.\"" },
  { zh: "當時吏職，何能悉治，論議之徒，豈不喧嘩！", literal: "\"At that time how could every official post be fully governed? Would not the faction of disputants have clamored!\"", idiomatic: "\"Could every post have been perfectly filled then? Would critics not have roared?\"" },
  { zh: "蓋以為天地之功不可倉卒，艱難之業當累日也。", literal: "\"Surely because the work of Heaven and earth cannot be rushed, and arduous enterprise must accumulate through days.\"", idiomatic: "\"Heaven's work cannot be rushed; great undertakings need time.\"" },
  { zh: "而間者守宰數見換易，迎新相代，疲勞道路。", literal: "\"Yet recently prefects and magistrates have repeatedly been replaced; welcoming the new and handing on to the next, the roads are worn with fatigue.\"", idiomatic: "\"Yet lately prefects and magistrates are swapped again and again—welcoming the new, seeing off the old—until the roads groan with their comings and goings.\"" },
  { zh: "尋其視事日淺，未足昭見其職，既加嚴切，人不自保，迫於舉劾，懼於刺譏，故爭飾詐偽以希虛譽，斯所以致日月失行之應也。", literal: "\"Search out their days in office—they are short, insufficient to make their duties manifest. Since strictness was added, men cannot preserve themselves; pressed by impeachment, fearful of censure and exposure, they therefore compete to adorn fraud and falsehood hoping for empty praise—this is what brings the response of sun and moon losing their course.\"", idiomatic: "\"They barely take office before they are moved on, with no time to prove themselves. Under harsh scrutiny men cannot stand secure; hunted by impeachment, dreading exposure, they vie to paint false fronts for hollow praise—and that brings the sun and moon out of their course.\"" },
  { zh: "夫物暴長者必夭折，功卒成者必亟壞。", literal: "\"Things that shoot up violently must perish young; achievements finished in a rush must soon break.\"", idiomatic: "\"What shoots up too fast must die young; what is finished in haste must soon crack.\"" },
  { zh: "如摧長久之業而造速成之功，非陛下之福也。", literal: "\"To dash long-standing enterprise and forge quick-completion achievement is not Your Majesty's blessing.\"", idiomatic: "\"To tear down long work for quick results is no blessing to Your Majesty.\"" },
  { zh: "願陛下遊意於經年之外，望治於一世之後，天下幸甚！", literal: "\"I wish Your Majesty would let your mind roam beyond mere years and look for good order after a whole age—the realm would be greatly blessed!\"", idiomatic: "\"May Your Majesty set your mind on years ahead and look for order after a generation—the realm would be blessed indeed!\"" },
  { zh: "」帝采其言，自是牧守易代頗簡。", literal: "\" The emperor adopted his words; from this the replacement of governors and defenders became rather sparing.", idiomatic: "\" The emperor took his counsel; thereafter provincial appointments changed less often." },
  { zh: "9〔冬〕，十二月<ref>〔冬〕十二月據《通鑑》通例補「冬」字。", literal: "9. 〔Winter〕, the twelfth month<ref>〔Winter〕—the character \"winter\" for the twelfth month is supplied per the Comprehensive Mirror's usual practice.", idiomatic: "9. 〔Winter〕, the twelfth month<ref>〔Winter〕—\"winter\" is supplied for the twelfth month per the Comprehensive Mirror's usual practice." },
  { zh: "</ref>，壬辰，大司空宋弘免。", literal: "</ref> On the day renchen, Grand Minister of Works Song Hong was dismissed.", idiomatic: "</ref> On renchen day Grand Minister of Works Song Hong was dismissed." },
  { zh: "10癸巳，詔曰：「頃者師旅未解，用度不足，故行十一之稅。", literal: "10. On the day guisi, an edict said: \"Recently armies and campaigns were not yet concluded; expenditures were insufficient—therefore the tax of one in eleven was imposed.\"", idiomatic: "10. On guisi day an edict said: \"While armies were still in the field and funds ran short, we levied one part in eleven.\"" },
  { zh: "今糧儲差積，其令郡國收見田租三十稅一，如舊制。", literal: "\"Now grain stores have somewhat accumulated; let commanderies and kingdoms collect the present field tax at one in thirty, as the old statute.\"", idiomatic: "\"Stores have begun to fill again. Let commanderies and kingdoms collect the field tax at one part in thirty, as of old.\"" },
  { zh: "11諸將之下隴也，帝詔耿弇軍漆，馮異軍栒邑，祭遵軍汧，吳漢等還屯長安。", literal: "11. When the generals came down from Long, the emperor ordered Geng Yan's army to Qi, Feng Yi's army to Xunyi, Ji Zun's army to Qian, and Wu Han and others to return and encamp at Chang'an.", idiomatic: "11. When the generals retreated from Long, the emperor posted Geng Yan at Qi, Feng Yi at Xunyi, Ji Zun at Qian, and Wu Han and the rest at Chang'an." },
  { zh: "馮異引軍未至栒邑，隗囂乘勝使王元、行巡將二萬餘人下隴，分遣巡取栒邑。", literal: "Feng Yi was leading his army but had not yet reached Xunyi when Wei Xiao, riding victory, sent Wang Yuan and Xing Xun with more than twenty thousand men down from Long, dispatching Xun in a separate detachment to take Xunyi.", idiomatic: "Feng Yi had not yet reached Xunyi when Wei Xiao, pressing his advantage, sent Wang Yuan and Xing Xun with more than twenty thousand men down from Long, and detached Xun to seize Xunyi." },
  { zh: "異即馳兵欲先據之，諸將曰：「虜兵盛而乘勝，不可與爭鋒，宜止軍便地，徐思方略。", literal: "Yi immediately spurred his troops wishing to seize it first; the generals said: \"The enemy's soldiers are numerous and riding victory—we cannot contend at the spearhead; we ought to halt the army on favorable ground and slowly devise strategy.\"", idiomatic: "Feng Yi spurred his men to seize the city first. His officers said, \"The enemy is strong and riding victory. We cannot meet them head-on. Halt on good ground and plan.\"" },
  { zh: "」異曰：「虜兵臨境，忸心犬小利，遂欲深入；", literal: "\" Yi said: \"The enemy's troops press the border, their hearts accustomed like dogs to small gain, and they wish at once to drive deep;", idiomatic: "\" Feng Yi said, \"The enemy is at our border, their hearts craven as dogs after small gain, and they mean to drive deep;\"" },
  { zh: "若得栒邑，三輔動搖。", literal: "\"if they gain Xunyi, the Three Metropolises will shake.\"", idiomatic: "\"if they take Xunyi, the Three Metropolises will shake.\"" },
  { zh: "夫攻者不足，守者有餘。", literal: "\"In attack the force is insufficient; in defense the defender has surplus.\"", idiomatic: "\"Attack lacks strength; defense has surplus.\"" },
  { zh: "今先據城，以逸待勞，非所以爭也。", literal: "\"Now to seize the city first, awaiting with ease their weariness—this is not the way to contend.\"", idiomatic: "\"Seize the city first and meet them fresh while they are weary—that is not contention at all.\"" },
  { zh: "」潛往，閉城，偃旗鼓。", literal: "\" He went secretly, closed the city, and lowered banners and drums.", idiomatic: "\" He went in secret, shut the city, and lowered banners and drums." },
  { zh: "行巡不知，馳赴之。", literal: "Xing Xun did not know and galloped to go there.", idiomatic: "Xing Xun did not know and galloped there." },
  { zh: "異乘其不意，卒擊鼓、建旗而出。", literal: "Yi seized their lack of expectation, suddenly beat drums and raised banners, and sallied out.", idiomatic: "Yi caught them off guard, suddenly beat drums, raised banners, and sallied out." },
  { zh: "巡軍驚亂奔走，追擊，大破之。", literal: "Xun's army panicked, scattered, and fled; they pursued and routed them utterly.", idiomatic: "Xun's army panicked and fled; they pursued and routed them utterly." },
  { zh: "祭遵亦破王元於汧。", literal: "Ji Zun also defeated Wang Yuan at Qian.", idiomatic: "Ji Zun also defeated Wang Yuan at Qian." },
  { zh: "於是北地諸豪長耿定等悉畔隗囂降。", literal: "Thereupon all the powerful men and elders of Beidi, including Geng Ding, entirely turned from Wei Ao and surrendered.", idiomatic: "Thereupon all the powerful men and elders of Beidi, including Geng Ding, turned from Wei Ao and surrendered." },
  { zh: "詔異進軍義渠，擊破盧芳將賈覽、匈奴奧鞬日逐王，北地、上郡、安定皆降。", literal: "An edict ordered Yi to advance the army to Yiqu, defeated Lu Fang's general Jia Lan and the Xiongnu Ao Jian Rizhu King; Beidi, Shang, and Anding all surrendered.", idiomatic: "An edict ordered Yi to advance to Yiqu, defeated Lu Fang's general Jia Lan and the Xiongnu Ao Jian Rizhu King, and Beidi, Shang, and Anding all surrendered." },
  { zh: "12竇融復遣其弟友上書曰：「臣幸得托先後末屬，累世二千石，臣復假歷將帥，守持一隅，故遣劉鈞口陳肝膽，自以底裡上露，長無纖介。", literal: "12 Dou Rong again sent his younger brother You to present a memorial, saying: \"Your servant was fortunate to rely on attachment to the former and latter imperial houses, for generations held the two-thousand-bushel offices; your servant again was lent successive service as commander, holding one corner, and therefore sent Liu Jun to state heart and liver by mouth, taking it that my inmost self was laid bare above and would long be without the slightest flaw.", idiomatic: "Dou Rong again sent his younger brother You to present a memorial, saying: \"I was fortunate to rely on attachment to the former and latter imperial houses; my family for generations held two-thousand-bushel offices; I have again served as commander and held one corner, and therefore sent Liu Jun to speak my heart openly, believing my inmost loyalty was laid bare and would long remain without the slightest flaw." },
  { zh: "而璽書盛稱蜀、漢二主三分鼎足之權，任囂、尉佗之謀，竊自痛傷。", literal: "Yet the imperial letter lavishly praised the two lords of Shu and Han and the power to divide the realm like a tripod cauldron, the schemes of Ren Xiao and Wei Tuo—I privately was pained and wounded.", idiomatic: "Yet the imperial letter lavishly praised the two lords of Shu and Han and the power to divide the realm like a tripod, the schemes of Ren Xiao and Wei Tuo—and I was privately pained and wounded." },
  { zh: "臣融雖無識，猶知利害之際、順逆之分。", literal: "Your servant Rong, though without understanding, still knows the juncture of benefit and harm and the distinction of compliance and defiance.", idiomatic: "I, Rong, though without great understanding, still know the juncture of benefit and harm and the distinction of compliance and defiance." },
  { zh: "豈可背真舊之主，事奸偽之人；", literal: "How could one turn against the true former lord and serve treacherous, false men;", idiomatic: "How could one turn against the true former lord and serve treacherous, false men;" },
  { zh: "廢忠貞小節，為傾覆之事；", literal: "abandon the small integrity of loyalty and constancy and do deeds of overthrow;", idiomatic: "abandon the small integrity of loyalty and constancy and do deeds of overthrow;" },
  { zh: "棄已成之基，求無冀之利。", literal: "cast away an already completed foundation and seek profit without hope.", idiomatic: "cast away an already completed foundation and seek profit without hope." },
  { zh: "此三者，雖問狂夫，猶知去就，而臣獨何以用心！", literal: "These three—though one asked a madman, he would still know departure and approach—yet why alone should your servant set his mind on them!", idiomatic: "These three—even a madman would know what to accept and reject—so why alone should I set my mind on them!" },
  { zh: "謹遣弟友詣闕，口陳至誠。", literal: "I respectfully send my younger brother You to the palace gate to state utmost sincerity by mouth.", idiomatic: "I respectfully send my younger brother You to court to speak my utmost sincerity in person." },
  { zh: "」友至高平，會隗囂反，道不通，乃遣司馬席封間道通書。", literal: "\" You reached Gaoping; it happened that Wei Ao rebelled and the road was not open, so he sent Marshal Xi Feng by a secret path to deliver the letter.", idiomatic: "\" You reached Gaoping, but Wei Ao had rebelled and the road was blocked, so he sent Marshal Xi Feng by a secret path to deliver the letter." },
  { zh: "帝復遣封，賜融、友書，所以尉藉之甚厚。", literal: "The Emperor again sent Feng back, bestowing letters on Rong and You—the means by which he comforted and reassured them were very generous.", idiomatic: "The Emperor again sent Feng back with letters for Rong and You, comforting and reassuring them very generously." },
  { zh: "融乃與隗囂書曰：「將軍親遇厄會之際，國家不利之時，守節不回，承事本朝。", literal: "Rong thereupon wrote to Wei Ao, saying: \"General, you personally met the juncture of calamity and the time when the state was unfavored, held your integrity without turning back, and continued to serve the dynasty.", idiomatic: "Rong then wrote to Wei Ao, saying: \"General, you personally met calamity and a time when the state was unfavored, held your integrity without turning back, and continued to serve the dynasty." },
  { zh: "融等所以欣服高義，願從役於將軍者，良為此也！", literal: "The reason Rong and the others rejoiced in and submitted to your lofty righteousness and wished to follow and serve under the general is truly for this!", idiomatic: "The reason we rejoiced in your lofty righteousness and wished to serve under you is truly this!" },
  { zh: "而忿悁之間，改節易圖，委成功，造難就，百年累之，一朝毀之，豈不惜乎！", literal: "Yet in a moment of anger you changed your integrity and altered your plan, abandoned success and created difficulty, what a hundred years had built up you destroyed in a morning—is it not to be regretted!", idiomatic: "Yet in a moment of anger you changed your integrity and altered your plan, abandoned success and created difficulty, destroyed in a morning what a hundred years had built—is that not to be regretted!" },
  { zh: "殆執事者貪功建謀，以至於此。", literal: "Perhaps those in charge, greedy for achievement, devised the plot and brought things to this.", idiomatic: "Perhaps those in charge, greedy for achievement, devised the plot and brought things to this." },
  { zh: "當今西州地勢局迫，民兵離散，易以輔人，難以自建。", literal: "Now the Western Province's terrain is cramped and pressing, militia and people scattered—it is easy to assist others and hard to stand on one's own.", idiomatic: "Now the Western Province is cramped, its militia and people scattered—it is easy to assist others and hard to stand on one's own." },
  { zh: "計若失路不反，聞道猶迷，不南合子陽，則北入文伯耳。", literal: "If the plan loses the road and does not return, hears the Way yet is still lost—if you do not join Ziyang in the south, then you will enter Wenbo in the north.", idiomatic: "If you lose the road and do not return, hear the Way yet remain lost—if you do not join Ziyang in the south, you will go to Wenbo in the north." },
  { zh: "夫負虛交而易強禦，恃遠救而輕近敵，未見其利也。", literal: "To bear empty friendship and lightly oppose the strong, to rely on distant rescue and slight a near enemy—its benefit is not seen.", idiomatic: "To rely on empty friendship and lightly oppose the strong, to count on distant rescue and slight a near enemy—its benefit is not seen." },
  { zh: "自兵起以來，城郭皆為丘墟，生民轉於溝壑。", literal: "Since troops rose, city walls and moats have all become mounds and ruins; the living people have been cast into ditches and gullies.", idiomatic: "Since the war began, cities have become ruins and the people cast into ditches and gullies." },
  { zh: "幸賴天運少還，而將軍復重其難，是使積痾不得遂瘳，幼孤將復流離，言之可為酸鼻。", literal: "Fortunately relying on Heaven's movement to return a little, yet the general again doubles the hardship—this makes accumulated illness unable to be healed at last, infants and orphans about to be cast adrift again; to speak of it can make the nose sting with sour grief.", idiomatic: "Fortunately Heaven's favor has begun to return, yet the general again doubles the hardship—this keeps accumulated ills from healing and will cast infants and orphans adrift again; to speak of it is heartbreaking." },
  { zh: "庸人且猶不忍，況仁者乎！", literal: "Even a mediocre man could not bear it—how much more a benevolent man!", idiomatic: "Even a mediocre man could not bear it—how much more a benevolent man!" },
  { zh: "融聞為忠甚易，得宜實難。", literal: "Rong has heard that doing loyalty is very easy, but obtaining what is fitting is truly hard.", idiomatic: "I have heard that doing loyalty is easy, but obtaining what is fitting is truly hard." },
  { zh: "憂人太過，以德取怨，知且以言獲罪也！", literal: "Worrying for others too much, by virtue one draws resentment—I know I shall yet be punished by words!", idiomatic: "To worry for others too much is to draw resentment by one's virtue—I know I shall yet be punished for these words!" },
  { zh: "」囂不納。", literal: "\" Ao did not accept it.", idiomatic: "\" Ao did not accept it." },
  { zh: "融乃與五郡太守共砥厲兵馬，上疏請師期；", literal: "Rong thereupon together with the five commandery governors jointly sharpened troops and horses and presented a memorial requesting a date for the army;", idiomatic: "Rong then together with the five commandery governors sharpened troops and horses and memorialized requesting a date for the army;" },
  { zh: "帝深嘉美之。", literal: "the Emperor deeply praised and admired it.", idiomatic: "the Emperor deeply praised it." },
  { zh: "融即與諸郡守將兵入金城，擊囂黨先零羌封何等，大破之。", literal: "Rong immediately together with the various commandery governors led troops into Jincheng, struck Ao's faction the Qiang of Xianling Feng He and others, and routed them utterly.", idiomatic: "Rong immediately led the commandery governors with troops into Jincheng, struck Ao's allies the Xianling Qiang Feng He and others, and routed them utterly." },
  { zh: "因並河，揚威武，伺候車駕。", literal: "He thereupon followed the river, displayed martial might, and awaited the imperial carriage.", idiomatic: "He then followed the river, displayed martial might, and awaited the imperial carriage." },
  { zh: "時大兵未進，融乃引還。", literal: "At the time the great army had not advanced; Rong thereupon withdrew and returned.", idiomatic: "The great army had not yet advanced, so Rong withdrew." },
  { zh: "帝以融信效著明，益嘉之，修理融父墳墓，祠以太牢，數馳輕使，致遺四方珍羞。", literal: "The Emperor, because Rong's faith and achievement were clearly outstanding, praised him the more, repaired Rong's father's tomb, sacrificed to it with the great offering, and repeatedly sent swift envoys bearing gifts of rare delicacies from the four directions.", idiomatic: "Because Rong's faith and achievement were clearly outstanding, the Emperor praised him further, repaired his father's tomb, sacrificed to it with the great offering, and repeatedly sent swift envoys bearing rare delicacies from the four directions." },
  { zh: "梁統猶恐眾心疑惑，乃使人刺殺張玄，遂與隗囂絕，皆解所假將軍印綬。", literal: "Liang Tong still feared the host's hearts were doubtful; he then had men assassinate Zhang Xuan, thereupon broke with Wei Ao, and all surrendered the borrowed general's seals and cords.", idiomatic: "Liang Tong still feared the troops were doubtful; he had Zhang Xuan assassinated, broke with Wei Ao, and all surrendered their borrowed general's seals and cords." },
  { zh: "13先是，馬援聞隗囂欲貳於漢，數以書責譬之，囂得書增怒。", literal: "13 Earlier, Ma Yuan heard that Wei Ao wished to waver toward Han and repeatedly by letter reproached and admonished him; Ao received the letters and grew angrier.", idiomatic: "Earlier, Ma Yuan heard that Wei Ao wished to waver toward Han and repeatedly reproached him by letter; Ao grew angrier with each letter." },
  { zh: "及囂發兵反，援乃上書曰：「臣與隗囂本實交友，初遣臣東，謂臣曰：『本欲為漢，願足下往觀之，於汝意可，即專心矣。", literal: "When Ao raised troops and rebelled, Yuan thereupon presented a memorial, saying: \"Your servant and Wei Ao were in truth friends; when he first sent your servant east he said to me: 'Originally I wished to serve Han; I hope you, sir, will go observe; if it suits your mind, then devote yourself wholeheartedly.", idiomatic: "When Ao raised troops and rebelled, Yuan presented a memorial, saying: \"Wei Ao and I were truly friends; when he first sent me east he said to me: 'Originally I wished to serve Han; I hope you will go observe; if it suits your mind, then devote yourself wholeheartedly." },
  { zh: "』及臣還反，報以赤心，實欲導之於善，非敢譎以非義。", literal: "' When your servant returned and reported with a red heart, he truly wished to guide him toward the good and did not dare deceive with what was not righteous.", idiomatic: "' When I returned and reported with a loyal heart, I truly wished to guide him toward the good and did not dare deceive him with what was not righteous." },
  { zh: "而囂自挾奸心，盜憎主人，怨毒之情，遂歸於臣。", literal: "Yet Ao on his own harbored a treacherous heart, hated his master like a thief, and the feeling of resentful poison thereupon turned upon your servant.", idiomatic: "Yet Ao on his own harbored treachery, hated his master like a thief, and his resentful poison turned upon me." },
  { zh: "臣欲不言，則無以上聞，願聽詣行在所，極陳滅囂之術。", literal: "Your servant wished not to speak, yet then there would be nothing to report above; I wish to be permitted to go to the traveling palace and set forth to the utmost the art of destroying Ao.", idiomatic: "If I wished not to speak, there would be nothing to report above; I ask permission to go to the traveling palace and set forth fully the art of destroying Ao." },
  { zh: "」帝乃召之。", literal: "\" The Emperor thereupon summoned him.", idiomatic: "\" The Emperor thereupon summoned him." },
  { zh: "援具言謀畫。", literal: "Yuan fully stated plans and designs.", idiomatic: "Yuan fully stated his plans." },
  { zh: "帝因使援將突騎五千，往來遊說囂將高峻、任禹之屬，下及羌豪，為陳禍福，以離囂支黨。", literal: "The Emperor thereupon had Yuan lead five thousand shock cavalry, go back and forth to persuade Ao's generals Gao Jun, Ren Yu, and their kind, down to the Qiang chieftains, set forth fortune and calamity for them, and thereby divide Ao's supporting factions.", idiomatic: "The Emperor had Yuan lead five thousand shock cavalry, go back and forth persuading Ao's generals Gao Jun, Ren Yu, and their kind, down to the Qiang chieftains, set forth fortune and calamity, and thereby divide Ao's supporters." },
  { zh: "援又為書與囂將楊廣，使曉勸於囂曰：「援竊見四海已定，兆民同情，而季孟閉拒背畔，為天下表的。", literal: "Yuan also wrote a letter to Ao's general Yang Guang, to have him enlighten and urge Ao, saying: \"Yuan has privately seen that within the four seas is settled, the myriad people share one feeling, yet Jimeng shuts himself off, refuses, and turns his back—he is a model for the world.", idiomatic: "Yuan also wrote to Ao's general Yang Guang to enlighten and urge Ao, saying: \"I have privately seen that within the four seas is settled and the myriad people share one feeling, yet Jimeng shuts himself off and rebels—he is a model for the world." },
  { zh: "常懼海內切齒，思相屠裂，故遺書戀戀，以致惻隱之計。", literal: "I constantly fear that within the seas people grind their teeth and think of slaughtering one another; therefore I sent letters full of longing to offer a plan of compassionate pity.", idiomatic: "I constantly fear that within the seas people grind their teeth and think of slaughtering one another; therefore I sent letters full of longing to offer a plan of compassionate pity." },
  { zh: "乃聞季孟歸罪於援，而納王游翁諂邪之說，因自謂函谷以西，舉足可定。", literal: "Yet I hear that Jimeng lays the blame on Yuan and accepts the flattery and wickedness of Wang Youweng's words, and therefore thinks that west of Hangu Pass, wherever he sets foot can be settled.", idiomatic: "Yet I hear that Jimeng lays the blame on me and accepts the flattery and wickedness of Wang Youweng's words, and therefore thinks that west of Hangu Pass he can settle everything wherever he sets foot." },
  { zh: "以今而觀，竟何如邪！", literal: "Viewed from today—how does it turn out after all!", idiomatic: "Viewed from today—how does it turn out after all!" },
  { zh: "援間至河內，過存伯春，見其奴吉從西方還，說伯春小弟仲舒望見吉，欲問伯春無它否，竟不能言，曉夕號泣，宛轉塵中。", literal: "Yuan by chance reached Henei, passed to inquire after Bochun, saw his slave Ji returning from the west, who said Bochun's younger brother Zhongshu, seeing Ji from afar, wished to ask whether Bochun was without other trouble, yet in the end could not speak, wept morning and evening, and writhed in the dust.", idiomatic: "Yuan by chance reached Henei and called on Bochun; he saw his slave Ji returning from the west, who said Bochun's younger brother Zhongshu, seeing Ji from afar, wished to ask whether Bochun was safe, yet could not speak, wept morning and evening, and writhed in the dust." },
  { zh: "又說其家悲愁之狀，不可言也。", literal: "He also spoke of the grief and sorrow of his household—unspeakable.", idiomatic: "He also spoke of his household's grief and sorrow—unspeakable." },
  { zh: "夫怨讎可刺不可毀，援聞之，不自知泣下也。", literal: "A foe of resentment may be stabbed but not destroyed; Yuan heard it and, without knowing it, wept.", idiomatic: "A foe of resentment may be stabbed but not destroyed; when Yuan heard it he wept without knowing it." },
  { zh: "援素知季孟孝愛，曾、閔不過。", literal: "Yuan has long known Jimeng's filial love—not surpassed by Zeng and Min.", idiomatic: "Yuan has long known Jimeng's filial love—not surpassed by Zeng and Min." },
  { zh: "夫孝於其親，豈不慈於其子！", literal: "If one is filial toward one's parents, how could one not be loving toward one's sons!", idiomatic: "If one is filial toward one's parents, how could one not be loving toward one's sons!" },
  { zh: "可有子抱三木而跳梁妄作，自同分羹之事乎！", literal: "Can there be a son who bears the triple cangue and capers in reckless rebellion, making himself the same as the affair of dividing the broth!", idiomatic: "Can there be a son who bears the cangue and capers in reckless rebellion, making himself the same as the affair of dividing the broth!" },
  { zh: "季孟平生自言所以擁兵眾者，欲以保全父母之國而完墳墓也，又言苟厚士大夫而已。", literal: "Jimeng in his life has himself said that the reason he gathered a host was to wish to preserve his parents' state and complete the tombs, and again said he wished only to treat scholars generously.", idiomatic: "Jimeng has himself said that the reason he gathered troops was to preserve his parents' state and complete the tombs, and that he wished only to treat scholars generously." },
  { zh: "而今所欲全者將破亡之，所欲完者將毀傷之，所欲厚者將反薄之。", literal: "Yet now what he wished to preserve will be destroyed and perish, what he wished to complete will be ruined and harmed, what he wished to treat generously will instead be treated thinly.", idiomatic: "Yet now what he wished to preserve will be destroyed, what he wished to complete will be ruined, what he wished to treat generously will instead be treated thinly." },
  { zh: "季孟嘗折愧子陽而不受其爵，今更共陸陸欲往附之，將難為顏乎！", literal: "Jimeng once humbled Ziyang in rebuke and did not accept his rank; now he again together, step by step, wishes to go attach to him—will it not be hard for the face!", idiomatic: "Jimeng once humbled Ziyang in rebuke and did not accept his rank; now he again wishes to go attach to him step by step—will that not be hard on his face!" },
  { zh: "若復責以重質，當安從得子主給是哉！", literal: "If again charged with heavy hostage, from where will he obtain a lord-son to supply this!", idiomatic: "If again charged with heavy hostages, from where will he obtain a lord's son to supply them!" },
  { zh: "往時子陽獨欲以王相待而春卿拒之，今者歸老，更欲低頭與小兒曹共槽櫪而食，並肩側身於怨家之朝乎！", literal: "In former times Ziyang alone wished to treat him as king and Chunqing refused; now, returning in old age, he again wishes to bow his head and with little boys share manger and trough to eat, shoulder to shoulder and body to body in the court of his enemy!", idiomatic: "In former times Ziyang alone wished to treat him as king and Chunqing refused; now, in old age, he again wishes to bow his head and with little boys share manger and trough, shoulder to shoulder in his enemy's court!" },
  { zh: "今國家待春卿意深，宜使牛孺卿與諸耆老大人共說季孟，若計畫不從，真可引領去矣。", literal: "Now the state treats Chunqing's intent deeply; you ought to have Niu Ruqing together with the various elders and great men jointly persuade Jimeng—if the plan is not followed, truly one may stretch the neck and go.", idiomatic: "Now the state treats Chunqing with deep intent; you ought to have Niu Ruqing together with the various elders jointly persuade Jimeng—if the plan is not followed, truly one may stretch the neck and go." },
  { zh: "前披輿地圖，見天下郡國百有六所，奈何欲以區區二邦以當諸夏百有四乎！", literal: "Earlier I spread the carriage-map and saw that the empire's commanderies and kingdoms number a hundred and six—how can one wish to use a mere two states to match the hundred and four of all Xia!", idiomatic: "Earlier I spread the carriage-map and saw that the empire's commanderies and kingdoms number a hundred and six—how can one wish to use a mere two states to match the hundred and four of all Xia!" },
  { zh: "春卿事季孟，外有君臣之義，內有朋友之道。", literal: "Chunqing serves Jimeng—outwardly there is the righteousness of ruler and minister, inwardly there is the Way of friends.", idiomatic: "Chunqing serves Jimeng—outwardly there is the righteousness of ruler and minister, inwardly there is the Way of friends." },
  { zh: "言君臣邪，固當諫爭；", literal: "Speaking as ruler and minister—certainly one ought to remonstrate and contend;", idiomatic: "Speaking as ruler and minister—certainly one ought to remonstrate;" },
  { zh: "語朋友邪，應有切磋。", literal: "speaking as friends—there ought to be grinding and polishing.", idiomatic: "speaking as friends—there ought to be mutual polishing." },
  { zh: "豈有知其無成，而但萎腇咋舌，義手從族乎！", literal: "How can there be knowing he has no success, yet only shrinking and stammering, folding arms and following the clan!", idiomatic: "How can one know he has no success, yet only shrink and stammer, fold one's arms and follow the clan!" },
  { zh: "及今成計，殊尚善也，過是，欲少味矣！", literal: "To achieve the plan by today is especially still good; past that, one will wish for a little less flavor!", idiomatic: "To achieve the plan today is especially still good; past that, it will lose much of its savor!" },
  { zh: "且來君叔天下信士，朝廷重之，其意依依，常獨為西州言。", literal: "Moreover Lai Junshu is a man of trust throughout the world; the court values him; his intent is lingering and constant; he alone often speaks for the Western Province.", idiomatic: "Moreover Lai Junshu is trusted throughout the world; the court values him; his intent is constant; he alone often speaks for the Western Province." },
  { zh: "援商朝廷，尤欲立信於此，必不負約。", literal: "Yuan has discussed with the court; they especially wish to establish trust here and will certainly not break the covenant.", idiomatic: "I have discussed with the court; they especially wish to establish trust here and will certainly not break the covenant." },
  { zh: "援不得久留，願急賜報。", literal: "Yuan cannot long remain; I wish you would urgently grant a reply.", idiomatic: "I cannot long remain; I wish you would urgently grant a reply." },
  { zh: "」廣竟不答。", literal: "\" Guang in the end did not reply.", idiomatic: "\" Guang in the end did not reply." },
  { zh: "諸將每有疑議，更請呼援，咸敬重焉。", literal: "Whenever the generals had doubtful points in discussion, they again requested Yuan be called—they all respected and honored him.", idiomatic: "Whenever the generals had doubtful points, they again requested Yuan be called—they all respected him." },
  { zh: "14隗囂上疏謝曰：「吏民聞大兵卒至，驚恐自救，臣囂不能禁止。", literal: "14 Wei Ao presented a memorial of apology, saying: \"Officials and people, hearing the great army suddenly arrive, were frightened and sought to save themselves—your servant Ao could not forbid it.", idiomatic: "Wei Ao presented a memorial of apology, saying: \"Officials and people, hearing the great army suddenly arrive, were frightened and sought to save themselves—I could not forbid it." },
  { zh: "兵有大利，不敢廢臣子之節，親自追還。", literal: "The troops had great advantage; I did not dare abandon the integrity of a subject and minister, and personally pursued and brought them back.", idiomatic: "The troops had great advantage; I did not dare abandon the integrity of a subject and minister and personally pursued and brought them back." },
  { zh: "昔虞舜事父，大杖則走，小杖則受，臣雖不敏，敢忘斯義！", literal: "Formerly Shun served his father: with a great staff he fled, with a small staff he accepted it—your servant, though not keen, dares forget this righteousness!", idiomatic: "Formerly Shun served his father: with a great staff he fled, with a small staff he accepted it—I, though not keen, dare not forget this righteousness!" },
  { zh: "今臣之事，在於本朝，賜死則死，加刑則刑；", literal: "Now your servant's affair lies with the dynasty—if death is granted then die, if punishment is added then suffer punishment;", idiomatic: "Now my affair lies with the dynasty—if death is granted then I die, if punishment is added then I suffer it;" },
  { zh: "如更得洗心，死骨不朽。", literal: "if again permitted to wash the heart, dead bones would not decay.", idiomatic: "if again permitted to wash my heart, even dead bones would not decay." },
  { zh: "」有司以囂言慢，請誅其子。", literal: "\" The responsible offices, because Ao's words were insolent, requested execution of his sons.", idiomatic: "\" The responsible offices, because Ao's words were insolent, requested execution of his sons." },
  { zh: "帝不忍，復使來歙至汧，賜囂書曰：「昔柴將軍云：『陛下寬仁，諸侯雖有亡叛而後歸，輒復位號，不誅也。", literal: "The Emperor could not bear it and again sent Lai Xi to Qian, bestowing on Ao a letter, saying: \"Formerly General Chai said: 'Your Majesty is broad and benevolent; though feudal lords have fled in rebellion and afterward returned, their ranks and titles are at once restored and they are not executed.", idiomatic: "The Emperor could not bear it and again sent Lai Xi to Qian with a letter for Ao, saying: \"Formerly General Chai said: 'Your Majesty is broad and benevolent; though feudal lords have fled in rebellion and afterward returned, their ranks and titles are at once restored and they are not executed." },
  { zh: "』今若束手，復遣恂弟歸闕庭者，則爵祿獲全，有浩大之福矣！", literal: "' Now if you bind your hands and again send Xun's younger brother back to the court, then rank and stipend will be wholly preserved and there will be vast blessing!", idiomatic: "' Now if you bind your hands and again send Xun's younger brother back to court, then rank and stipend will be wholly preserved and there will be vast blessing!" },
  { zh: "吾年垂四十，在兵中十歲，厭浮語虛辭。", literal: "I am nearly forty, ten years in the army—I am weary of floating words and empty phrases.", idiomatic: "I am nearly forty, ten years in the army—I am weary of empty phrases." },
  { zh: "即不欲，勿報。", literal: "If you do not wish it, do not reply.", idiomatic: "If you do not wish it, do not reply." },
  { zh: "」囂知帝審其詐，遂遣使稱臣於公孫述。", literal: "\" Ao knew the Emperor had penetrated his deceit and thereupon sent envoys to declare himself a subject to Gongsun Shu.", idiomatic: "\" Ao knew the Emperor had penetrated his deceit and sent envoys to declare himself a subject to Gongsun Shu." },
  { zh: "15匈奴與盧芳為寇不息，帝令歸德侯颯使匈奴以修舊好。", literal: "15 The Xiongnu together with Lu Fang raided without cease; the Emperor ordered Marquis of Guide Sa as envoy to the Xiongnu to restore the old friendship.", idiomatic: "The Xiongnu together with Lu Fang raided without cease; the Emperor ordered Marquis of Guide Sa as envoy to the Xiongnu to restore the old friendship." },
  { zh: "單于驕倨，雖遣使報命，而寇暴如故。", literal: "The chanyu was arrogant and insolent; though he sent envoys to return the mission, plunder and violence were as before.", idiomatic: "The chanyu was arrogant; though he sent envoys to return the mission, plunder and violence continued as before." },
  { zh: "1春，三月，罷郡國輕車、騎士、材官，今還復民伍。", literal: "1 In spring, the third month, the commanderies' and kingdoms' light chariots, knights, and materiel officers were dismissed and ordered to return to the common people's companies.", idiomatic: "In spring, the third month, the commanderies' and kingdoms' light chariots, knights, and materiel officers were dismissed and ordered to return to the common people's companies." },
  { zh: "2公孫述立隗囂為朔寧王，遣兵往來，為之援勢。", literal: "2 Gongsun Shu established Wei Ao as King of Shuoning, sent troops back and forth, and made supporting momentum for him.", idiomatic: "Gongsun Shu established Wei Ao as King of Shuoning, sent troops back and forth, and supported him." },
  { zh: "3癸亥晦，日有食之。", literal: "3 On the last day of guihai, there was an eclipse of the sun.", idiomatic: "On the last day of guihai there was a solar eclipse." },
  { zh: "詔百僚各上封事，其上書者不得言聖，太中大夫鄭興上疏曰：「夫國無善政，則謫見日月。", literal: "An edict ordered the hundred officials each to present sealed memorials; those who presented memorials might not speak of sageliness; Grand Master of the Palace Zheng Xing presented a memorial, saying: \"When the state has no good government, reproof appears in the sun and moon.", idiomatic: "An edict ordered the hundred officials each to present sealed memorials; memorialists might not speak of sageliness; Grand Master of the Palace Zheng Xing presented a memorial, saying: \"When the state has no good government, reproof appears in the sun and moon." },
  { zh: "要在因人之心，擇人處位。", literal: "The key lies in following people's hearts and choosing men to place in positions.", idiomatic: "The key lies in following people's hearts and choosing men to place in positions." },
  { zh: "今公卿大夫多舉漁陽太守郭人及可大司空者，而不以時定；", literal: "Now the high ministers and grand masters mostly recommend Guo Ren, governor of Yuyang, and one fit for Grand Minister of Works, yet do not settle it in good time;", idiomatic: "Now the high ministers mostly recommend Guo Ren, governor of Yuyang, and one fit for Grand Minister of Works, yet do not settle it in good time;" },
  { zh: "道路流言，咸曰『朝廷欲用功臣』，功臣用則人位謬矣。", literal: "roadside rumor all says 'The court wishes to employ meritorious ministers'—if meritorious ministers are employed, then men's positions are wrong.", idiomatic: "roadside rumor says 'The court wishes to employ meritorious ministers'—if meritorious ministers are employed, then men's positions are wrong." },
  { zh: "願陛下屈己從眾，以濟群臣讓善之功。", literal: "I wish Your Majesty would bend yourself and follow the multitude, thereby completing the merit of the ministers yielding what is good.", idiomatic: "I wish Your Majesty would bend yourself and follow the multitude, thereby completing the ministers' merit in yielding what is good." },
  { zh: "頃年日食多在晦<ref>頃年日食多在晦章校「十二行本『多』上有『每』字；", literal: "In recent years solar eclipses have mostly been on the last day of the month<ref>In recent years solar eclipses have mostly been on the last day of the month—Zhang's collation: \"In the twelve-line edition above 'mostly' is the character 'each';\"", idiomatic: "In recent years solar eclipses have mostly been on the last day of the month<ref>In recent years solar eclipses have mostly been on the last day of the month: Zhang's collation—the twelve-line edition has the character \"each\" above \"mostly\";" },
  { zh: "乙十一行本同；", literal: "the Yi eleven-line edition agrees;", idiomatic: "the Yi eleven-line edition agrees;" },
  { zh: "孔本同。", literal: "Kong's edition agrees.", idiomatic: "Kong's edition agrees." },
  { zh: "」然不補亦可。", literal: "\" Yet not supplying it is also acceptable.", idiomatic: "\" Yet not supplying it is also acceptable." },
  { zh: "</ref>，先時而合，皆月行疾也。", literal: "</ref> early conjunction—all because the moon moves swiftly.", idiomatic: "</ref> early conjunction—all because the moon moves swiftly." },
  { zh: "日君象而月臣象；", literal: "The sun is the image of the ruler and the moon the image of the minister;", idiomatic: "The sun is the image of the ruler and the moon the image of the minister;" },
  { zh: "君亢急而臣下促迫，故月行疾。", literal: "the ruler is overbearing and urgent while subjects below are pressed and cramped—therefore the moon moves swiftly.", idiomatic: "the ruler is overbearing and urgent while subjects below are pressed and cramped—therefore the moon moves swiftly." },
  { zh: "今陛下高明而群臣惶促，宜留思柔克之政，垂意《洪範》之法。", literal: "Now Your Majesty is lofty and bright while the ministers are fearful and pressed; you ought to ponder long a policy of gentle overcoming, and attend to the methods of the Hong Fan.", idiomatic: "Now Your Majesty is lofty and bright while the ministers are fearful and pressed; you ought to ponder long a policy of gentle overcoming and attend to the methods of the Hong Fan." },
  { zh: "」帝躬勤政事，頗傷嚴急，故興奏及之。", literal: "\" The Emperor personally attended diligently to government affairs and was rather severe and urgent; therefore Xing's memorial touched on this.", idiomatic: "\" The Emperor personally attended diligently to government affairs and was rather severe and urgent; therefore Xing's memorial touched on this." },
  { zh: "4夏，四月，壬午，大赦。", literal: "4 In summer, the fourth month, on the day renwu, a general amnesty.", idiomatic: "In summer, the fourth month, on the day renwu, a general amnesty was proclaimed." },
  { zh: "5五月，戊戌，以前將軍李通為大司空。", literal: "5 In the fifth month, on the day wuxu, the former General-in-Chief Li Tong was made Grand Minister of Works.", idiomatic: "In the fifth month, on the day wuxu, the former General-in-Chief Li Tong was made Grand Minister of Works." },
  { zh: "6大司農江馮上言：「宜令司隸校尉督察三公。", literal: "6 Grand Minister of Agriculture Jiang Feng submitted a memorial: \"The Director of the Retainers ought to be ordered to inspect and supervise the Three Excellencies.", idiomatic: "Grand Minister of Agriculture Jiang Feng submitted a memorial: \"The Director of the Retainers ought to inspect and supervise the Three Excellencies." },
  { zh: "」司空掾陳元上疏曰：「臣聞師臣者帝，賓臣者霸。", literal: "\" Aide to the Minister of Works Chen Yuan submitted a memorial, saying: \"Your servant has heard: he who has a teacher as minister becomes an emperor; he who has a guest as minister becomes a hegemon.", idiomatic: "\" Aide to the Minister of Works Chen Yuan submitted a memorial, saying, \"I have heard that a ruler with a teacher as minister becomes an emperor, and one with a guest as minister becomes a hegemon." },
  { zh: "故武王以太公為師，齊桓以夷吾為仲父，近則高帝優相國之禮，太宗假宰輔之權。", literal: "Therefore King Wu of Zhou made Taigong his teacher; Duke Huan of Qi made Yiwu his zhongfu; recently the High Emperor showed exceptional courtesy to the Chancellor, and the Founding Emperor entrusted the chief ministers with full authority.", idiomatic: "King Wu of Zhou made Taigong his teacher; Duke Huan of Qi made Yiwu his zhongfu; recently the High Emperor showed exceptional courtesy to the Chancellor, and Emperor Wen entrusted the chief ministers with full authority." },
  { zh: "及亡新王莽，遭漢中衰，專操國柄以偷天下，況己自喻，不信群臣，奪公輔之任，損宰相之威，以刺舉為明，徼訐為直，至乃陪僕告其君長，子弟變其父兄，罔密法峻，大臣無所措手足；", literal: "When the fallen Xin of Wang Mang met Han in mid-decline, he monopolized the state's handle to steal the realm, moreover took himself as the standard, did not trust his ministers, stripped the Three Excellencies of their duties, diminished the Chancellor's authority, took denunciation and investigation as enlightenment, took petty accusations as uprightness, until attendants and servants denounced their lords and superiors and sons and younger brothers turned against fathers and elder brothers—laws were tangled and severe, and great ministers had nowhere to set hand or foot;", idiomatic: "When Wang Mang's fallen Xin met Han in mid-decline, he monopolized state power to steal the realm, prided himself on self-comparison, distrusted his ministers, stripped the Three Excellencies of their duties, diminished the Chancellor's authority, treated denunciation as enlightenment and petty accusations as uprightness, until servants denounced their lords and sons turned against fathers—laws were tangled and severe, and great ministers had nowhere to set hand or foot;" },
  { zh: "然不能禁董忠之謀，身為世戮。", literal: "yet he could not suppress Dong Zhong's plot and himself became a slaughter for the age.", idiomatic: "yet he could not suppress Dong Zhong's plot and himself became a byword for slaughter." },
  { zh: "方今四方尚擾，天下未一，百姓觀聽，咸張耳目。", literal: "Now the four quarters are still disturbed, the realm is not yet one, the common people watch and listen, all stretching eyes and ears.", idiomatic: "Now the four quarters are still disturbed, the realm is not yet united, and the common people watch and listen with eyes and ears wide open." },
  { zh: "陛下宜修文、武之聖典，襲祖宗之遺德，勞心下士，屈節待賢，誠不宜使有司察公輔之名。", literal: "Your Majesty ought to restore the sage canons of Wen and Wu, inherit the legacy virtue of the ancestors, toil in heart to humble yourself before scholars, bend your dignity to await the worthy—it truly is not fitting to let the responsible offices inspect the names of the Three Excellencies.", idiomatic: "Your Majesty ought to restore the sage canons of Wen and Wu, inherit the ancestors' legacy virtue, toil to humble yourself before scholars, and bend your dignity to await the worthy—it is truly not fitting to let the responsible offices inspect the Three Excellencies." },
  { zh: "」帝從之。", literal: "\" The Emperor followed this.", idiomatic: "\" The Emperor agreed." },
  { zh: "7酒泉太守竺曾以弟報怨殺人，自免去郡；", literal: "7 Administrator of Jiuquan Zhu Ceng, because his younger brother killed a man to avenge a grudge, himself resigned and left the commandery;", idiomatic: "Administrator of Jiuquan Zhu Ceng, because his younger brother killed a man to avenge a grudge, resigned and left the commandery;" },
  { zh: "竇融承製拜曾武鋒將軍，更以辛肜為酒泉太守。", literal: "Dou Rong by imperial order enfeoffed Ceng as Martial Vanguard General and replaced him with Xin Yin as Administrator of Jiuquan.", idiomatic: "Dou Rong by imperial order made Ceng Martial Vanguard General and replaced him with Xin Yin as Administrator of Jiuquan." },
  { zh: "8秋，隗囂將步騎三萬侵安定，至陰槃，馮異率諸將拒之；", literal: "8 In autumn Wei Ao led thirty thousand infantry and cavalry to invade Anding, reaching Yinpan; Feng Yi led the generals to resist him;", idiomatic: "In autumn Wei Ao led thirty thousand infantry and cavalry to invade Anding and reached Yinpan; Feng Yi led the generals to resist him;" },
  { zh: "囂又令別將下隴攻祭遵於汧。", literal: "Ao also ordered a separate general to descend Long and attack Ji Zun at Qian.", idiomatic: "Ao also ordered a separate general to descend Long and attack Ji Zun at Qian." },
  { zh: "並無利而還。", literal: "Both gained no advantage and returned.", idiomatic: "Both gained no advantage and withdrew." },
  { zh: "帝將自征隗囂，先戒竇融師期，會遇雨，道斷，且囂兵已退，乃止。", literal: "The Emperor was about to campaign in person against Wei Ao and first warned Dou Rong of the army's rendezvous date; he happened to meet rain, roads were cut, and moreover Ao's troops had already withdrawn, and he thereupon stopped.", idiomatic: "The Emperor was about to campaign in person against Wei Ao and first warned Dou Rong of the army's rendezvous date; rain cut the roads, Ao's troops had already withdrawn, and he stopped." },
  { zh: "帝令來歙以書招王遵，遵來降，拜太中大夫，封向義侯。", literal: "The Emperor ordered Lai Xi to recruit Wang Zun by letter; Zun came to surrender, was appointed Grand Master of the Palace, and enfeoffed as Marquis of Xiangyi.", idiomatic: "The Emperor ordered Lai Xi to recruit Wang Zun by letter; Zun surrendered, was appointed Grand Master of the Palace, and enfeoffed as Marquis of Xiangyi." },
  { zh: "9冬，盧芳以事誅其五原太守李興兄弟。", literal: "9 In winter Lu Fang on some pretext executed Administrator of Wuyuan Li Xing and his brothers.", idiomatic: "In winter Lu Fang on some pretext executed Administrator of Wuyuan Li Xing and his brothers." },
  { zh: "其朔方太守田颯、雲中太守喬扈各舉郡降，旁令領職如故。", literal: "His Administrators of Shuofang Tian Sa and Yunzhong Qiao Hu each led their commanderies to surrender; the Emperor ordered them to hold their posts as before.", idiomatic: "His Administrators of Shuofang Tian Sa and Yunzhong Qiao Hu each led their commanderies to surrender; the Emperor let them hold their posts as before." },
  { zh: "10帝好圖讖，與鄭興議郊祀事，曰：「吾欲以讖斷之，何如？", literal: "10 The Emperor was fond of prognostic charts and discussed suburban sacrifices with Zheng Xing, saying: \"I wish to decide it by omens—what do you think?", idiomatic: "The Emperor was fond of prognostic charts and discussed suburban sacrifices with Zheng Xing, saying, \"I wish to decide it by omens—what do you think?\"" },
  { zh: "」對曰：「臣不為讖。", literal: "\" He replied: \"Your servant does not produce omens.", idiomatic: "\" He replied, \"I do not produce omens.\"" },
  { zh: "」帝怒曰：「卿不為讖，非之邪？", literal: "\" The Emperor angrily said: \"You do not produce omens—you oppose them, do you not?", idiomatic: "\" The Emperor angrily said, \"You do not produce omens—you oppose them, do you?\"" },
  { zh: "」興惶恐曰：「臣於書有所未學，而無所非也。", literal: "\" Xing in fear said: \"Your servant in the classics has what he has not yet studied, but has nothing he rejects.", idiomatic: "\" Xing said in fear, \"There are things in the classics I have not yet studied, but nothing I reject.\"" },
  { zh: "」帝意乃解。", literal: "\" The Emperor's mood thereupon eased.", idiomatic: "\" The Emperor's mood thereupon eased." },
  { zh: "11南陽太守杜詩政治清平，興利除害，百姓便之。", literal: "11 Administrator of Nanyang Du Shi's government was clear and level; he promoted benefit and removed harm, and the common people found it convenient.", idiomatic: "Administrator of Nanyang Du Shi's government was clear and fair; he promoted benefit and removed harm, and the common people found it convenient." },
  { zh: "又修治陂池，廣拓土田，郡內比室殷足，時人方於召信臣。", literal: "He also repaired dikes and ponds, broadly expanded fields, and within the commandery household after household was well provided; men of the time compared him to Zhaoxin Chen.", idiomatic: "He also repaired dikes and ponds and broadly expanded fields; within the commandery household after household was well provided, and men of the time compared him to Zhaoxin Chen." },
  { zh: "南陽為之語曰：「前有召父，後有杜母。", literal: "Nanyang made a saying of it: \"Before there was Father Zhao; after there is Mother Du.", idiomatic: "Nanyang had a saying: \"Before there was Father Zhao; after there is Mother Du.\"" },
  { zh: "1春，來歙將二千餘人伐山開道，從番須、回中徑襲略陽，斬隗囂守將金梁。", literal: "1 In spring Lai Xi led more than two thousand men to cut through mountains and open roads, from Fanxu and Huizhong by a direct path to strike Lueyang, and beheaded Wei Ao's garrison general Jin Liang.", idiomatic: "In spring Lai Xi led more than two thousand men to cut through mountains and open roads, came by Fanxu and Huizhong on a direct path to strike Lueyang, and beheaded Wei Ao's garrison general Jin Liang." },
  { zh: "囂大驚曰：「何其神也！", literal: "Ao was greatly alarmed and said: \"How divine!", idiomatic: "Ao was greatly alarmed and said, \"How divine!\"" },
  { zh: "」帝聞得略陽，甚喜，曰：「略陽，囂所依阻。", literal: "\" When the Emperor heard Lueyang had been taken, he was greatly pleased and said: \"Lueyang is what Ao relies on for defense.", idiomatic: "\" When the Emperor heard Lueyang had been taken, he was greatly pleased and said, \"Lueyang is what Ao relies on for defense." },
  { zh: "心腹已壞，則制其支體易矣！", literal: "The heart and belly are already ruined—then controlling his limbs and trunk will be easy!", idiomatic: "His heart and belly are already ruined—then controlling his limbs will be easy!\"" },
  { zh: "吳漢等諸將聞歙據略陽，爭馳赴之。", literal: "The generals Wu Han and the others, hearing Xi held Lueyang, vied to gallop to join him.", idiomatic: "Generals Wu Han and the others, hearing Xi held Lueyang, all raced to join him." },
  { zh: "上以為囂失所恃，亡其要城，勢必悉以精銳來攻；", literal: "The Emperor thought that Ao had lost what he relied on and lost his key city, and was certain to bring all his elite troops to attack;", idiomatic: "The Emperor thought Ao had lost his support and his key city and was certain to bring all his elite troops to attack;" },
  { zh: "曠日久圍而城不拔，士卒頓敝，乃可乘危而進，皆追漢等還。", literal: "if the siege dragged on for days without taking the city, the soldiers would be worn and exhausted, and then one could advance on their peril—all were ordered to recall Han and the others.", idiomatic: "if the siege dragged on without taking the city the troops would be worn out, and then one could advance on their peril—he ordered Han and the others recalled." },
  { zh: "隗囂果使王元拒隴坻，行巡守番須口，王孟塞雞頭道，牛邯軍瓦亭。", literal: "Wei Ao indeed sent Wang Yuan to hold Longdi, Xing Xun to guard the mouth of Fanxu, Wang Meng to block Jitou Pass, and Niu Han to encamp at Wating.", idiomatic: "Wei Ao sent Wang Yuan to hold Longdi, Xing Xun to guard the mouth of Fanxu, Wang Meng to block Jitou Pass, and Niu Han to encamp at Wating." },
  { zh: "囂自悉其大眾數萬人圍略陽，公孫述遣將李育、田弇助之，斬山築堤，激水灌城。", literal: "Ao himself mustered his great host of tens of thousands to besiege Lueyang; Gongsun Shu sent generals Li Yu and Tian Yan to assist; they cut mountains and built dikes, channeled water to flood the city.", idiomatic: "Ao himself mustered tens of thousands to besiege Lueyang; Gongsun Shu sent Li Yu and Tian Yan to assist; they cut mountains, built dikes, and channeled water to flood the city." },
  { zh: "來歙與將士固死堅守，矢盡，發屋斷木以為兵。", literal: "Lai Xi with the officers and soldiers staunchly held to the death; when arrows were exhausted, they tore apart houses and broke wood to make weapons.", idiomatic: "Lai Xi and his officers and soldiers held staunchly to the death; when arrows ran out they tore apart houses and broke wood for weapons." },
  { zh: "囂盡銳攻之，累月不能下。", literal: "Ao exhausted his elite in attacking it for months but could not take it.", idiomatic: "Ao threw all his elite into the attack for months but could not take it." },
  { zh: "夏，閏四月，帝自將征隗囂，光祿勳汝南郭憲諫曰：「東方初定，車駕未可遠征。", literal: "In summer, in the intercalary fourth month, the Emperor himself led a campaign against Wei Ao; Bearer of the Cap and Scepter Guo Xian of Runan remonstrated, saying: \"The east has only just been settled—the imperial carriage must not make a distant campaign.", idiomatic: "In summer, in the intercalary fourth month, the Emperor led a campaign in person against Wei Ao; Bearer of the Cap and Scepter Guo Xian of Runan remonstrated, \"The east has only just been settled—the imperial carriage must not campaign so far.\"" },
  { zh: "」乃當車拔佩刀以斷車靷。", literal: "\" He thereupon stood before the carriage, drew his girdle-sword, and cut the traces.", idiomatic: "\" He stood before the carriage, drew his sword, and cut the traces." },
  { zh: "帝不從，西至漆。", literal: "The Emperor did not follow this and went west as far as Qi.", idiomatic: "The Emperor did not listen and went west as far as Qi." },
  { zh: "諸將多以王師之重，不宜遠入險阻，計冘豫未決；", literal: "Many of the generals, on the grounds that the imperial army's weight made it unsuitable to enter far into perilous passes, had plans hesitant and undecided;", idiomatic: "Many generals held that the imperial army was too weighty to enter far into perilous passes, and plans were hesitant and undecided;" },
  { zh: "帝召馬援問之。", literal: "the Emperor summoned Ma Yuan to question him.", idiomatic: "the Emperor summoned Ma Yuan to ask his view." },
  { zh: "援因說隗囂將帥有土崩之勢，兵進有必破之狀；", literal: "Yuan thereupon explained that Wei Ao's generals and commanders were in a posture of collapsing like earth, and that if the army advanced there was the certainty of breaking them;", idiomatic: "Yuan explained that Wei Ao's generals were on the verge of collapse and that if the army advanced it was certain to break them;" },
  { zh: "又於帝前聚米為山谷，指畫形勢，開示眾軍所從道徑，往來分析，昭然可曉。", literal: "moreover before the Emperor he piled rice to make mountains and valleys, traced the terrain, disclosed the routes the host would take, analyzed coming and going, clear and intelligible.", idiomatic: "and before the Emperor piled rice into mountains and valleys, traced the terrain, showed the routes the army would take, and analyzed the movements so clearly that all could understand." },
  { zh: "帝曰：「虜在吾目中矣！", literal: "The Emperor said: \"The foe is already in my eyes!", idiomatic: "The Emperor said, \"The foe is already in my sight!\"" },
  { zh: "」明旦，遂進軍，至高平第一。", literal: "\" The next morning he thereupon advanced the army to Gaoping Di Yi.", idiomatic: "\" The next morning he advanced the army to Gaoping Di Yi." },
  { zh: "竇融率五郡太守及羌虜小月氏等步騎數萬，輜重五千餘兩，與大軍會。", literal: "Dou Rong led the five commandery administrators and Lesser Yuezhi and other Qiang and barbarian infantry and cavalry numbering tens of thousands, with more than five thousand supply wagons, and joined the great army.", idiomatic: "Dou Rong led the five commandery administrators and Lesser Yuezhi and other Qiang and barbarian infantry and cavalry numbering tens of thousands, with more than five thousand supply wagons, and joined the main army." },
  { zh: "是時軍旅草創，諸將朝會禮容多不肅，融先遣從事問會見儀適。", literal: "At this time the army was newly formed; at court assemblies many generals' ceremonial bearing was not respectful; Rong first sent an attendant to inquire about the proper etiquette for audience.", idiomatic: "The army was newly formed; at court assemblies many generals' ceremonial bearing was lax; Rong first sent an attendant to inquire about the proper etiquette for audience." },
  { zh: "帝聞而善之，以宣告百僚，乃置酒高會，待融等以殊禮。", literal: "The Emperor heard and approved, proclaimed it to the hundred officials, then set out wine for a grand gathering and treated Rong and the others with exceptional courtesy.", idiomatic: "The Emperor heard and approved, proclaimed it to the hundred officials, set out wine for a grand gathering, and treated Rong and the others with exceptional courtesy." },
  { zh: "遂共進軍，數道上隴。", literal: "They thereupon advanced together, on several routes ascending Long.", idiomatic: "They advanced together on several routes up Long." },
  { zh: "使王遵以書招牛邯，下之，拜邯太中大夫。", literal: "He had Wang Zun recruit Niu Han by letter; Han submitted, was appointed Grand Master of the Palace.", idiomatic: "Wang Zun recruited Niu Han by letter; Han submitted and was appointed Grand Master of the Palace." },
  { zh: "於是囂大將十三人、屬縣十六、眾十餘萬皆降。", literal: "Thereupon thirteen of Ao's great generals, sixteen subordinate counties, and a host of more than a hundred thousand all surrendered.", idiomatic: "Thereupon thirteen of Ao's great generals, sixteen subordinate counties, and more than a hundred thousand men all surrendered." },
  { zh: "囂將妻子奔西城，從楊廣，而田弇、李育保上邽。", literal: "Ao led his wife and children to flee to Xicheng and followed Yang Guang, while Tian Yan and Li Yu held Shanggui.", idiomatic: "Ao fled with his wife and children to Xicheng and followed Yang Guang, while Tian Yan and Li Yu held Shanggui." },
  { zh: "略陽圍解。", literal: "The siege of Lueyang was lifted.", idiomatic: "The siege of Lueyang was lifted." },
  { zh: "帝勞賜來歙，班坐絕席，在諸將之右，賜歙妻縑千匹。", literal: "The Emperor rewarded and gifted Lai Xi, seating him on a separate mat apart from the others, to the right of the generals, and gifted Xi's wife a thousand bolts of fine silk.", idiomatic: "The Emperor rewarded Lai Xi, gave him a separate mat to the right of the generals, and gifted his wife a thousand bolts of fine silk." },
  { zh: "進幸上邽，詔告隗囂曰：「若束手自詣，父子相見，保無佗也。", literal: "He advanced in person to Shanggui and issued an edict telling Wei Ao: \"If you bind yourself and come in person, father and son will meet—I guarantee you no other harm.", idiomatic: "He advanced to Shanggui and issued an edict to Wei Ao: \"If you bind yourself and come in person, father and son will meet—I guarantee you no other harm.\"" },
  { zh: "若遂欲為黥布者，亦自任也。", literal: "If you persist in wishing to be like Qing Bu, that too is your own choice.", idiomatic: "If you persist in being like Qing Bu, that is your own choice.\"" },
  { zh: "」囂終不降，於是誅其子恂。", literal: "\" Ao to the end did not surrender; the Emperor thereupon executed his son Xun.", idiomatic: "\" Ao never surrendered; the Emperor thereupon executed his son Xun." },
  { zh: "使吳漢、岑彭圍西城，耿弇、蓋延圍上邽。", literal: "He sent Wu Han and Cen Peng to besiege Xicheng, Geng Yan and Gai Yan to besiege Shanggui.", idiomatic: "He sent Wu Han and Cen Peng to besiege Xicheng and Geng Yan and Gai Yan to besiege Shanggui." },
  { zh: "以四縣封竇融為安豐侯，弟友為顯親侯，及五郡太守皆封列侯，遣西還所鎮。", literal: "With four counties he enfeoffed Dou Rong as Marquis of Anfeng, his younger brother You as Marquis of Xianqin, and all five commandery administrators were enfeoffed as ranked marquises and sent west to return to their posts.", idiomatic: "With four counties he enfeoffed Dou Rong as Marquis of Anfeng and his younger brother You as Marquis of Xianqin; all five commandery administrators were enfeoffed as ranked marquises and sent west to their posts." },
  { zh: "融以久專方面，懼不自安，數上書求代。", literal: "Rong, because he had long held independent authority in his region, feared he could not be secure and several times submitted memorials requesting replacement.", idiomatic: "Rong, having long held independent authority in his region, feared for his security and several times asked to be replaced." },
  { zh: "詔報曰：「吾與將軍如左右手耳，數執謙退，何不曉人意！", literal: "An edict in reply said: \"I and the general are like left and right hands—why again and again hold to modest withdrawal and not understand another's intent!", idiomatic: "The edict replied, \"You and I are like left and right hands—why again and again insist on modest withdrawal and not understand my intent!\"" },
  { zh: "勉循士民，無擅離部曲！", literal: "Urge yourself on in governing scholars and commoners—do not on your own leave your command!", idiomatic: "Press on in governing your people—do not leave your command on your own!\"" },
  { zh: "穎川盜賊群起，寇沒屬縣，河東守兵亦叛，京師騷動。", literal: "Bandits in Yingchuan rose in groups, raided and overran subordinate counties, garrison troops in Hedong also rebelled, and the capital was disturbed.", idiomatic: "Bandits in Yingchuan rose in groups, raided subordinate counties, garrison troops in Hedong rebelled, and the capital was disturbed." },
  { zh: "帝聞之曰：「吾悔不用郭子橫之言。", literal: "The Emperor, hearing of it, said: \"I regret not having used Guo Ziheng's words.", idiomatic: "The Emperor said, \"I regret not having taken Guo Ziheng's advice.\"" },
  { zh: "秋，八月，帝自上邽晨夜東馳，賜岑彭等書曰：「兩城若下，便可將兵南擊蜀虜。", literal: "In autumn, the eighth month, the Emperor from Shanggui day and night galloped east and sent a letter to Cen Peng and the others, saying: \"If the two cities fall, you may at once lead troops south to strike the Shu foe.", idiomatic: "In autumn, the eighth month, the Emperor galloped east day and night from Shanggui and wrote Cen Peng and the others: \"If the two cities fall, you may at once lead troops south to strike the Shu foe.\"" },
  { zh: "人苦不知足，既平隴，復望蜀。", literal: "Men suffer from not knowing sufficiency—having pacified Long, they look again to Shu.", idiomatic: "Men never know sufficiency—having pacified Long, they look again to Shu." },
  { zh: "每一發兵，頭鬚為白！", literal: "Every time troops are dispatched, my hair and beard turn white!", idiomatic: "Every time I dispatch troops, my hair and beard turn white!\"" },
  { zh: "九月，乙卯，車駕還宮。", literal: "In the ninth month, on the day yimao, the imperial carriage returned to the palace.", idiomatic: "In the ninth month, on the day yimao, the imperial carriage returned to the palace." },
  { zh: "帝謂執金吾寇恂曰：「穎川迫近京師，當以時定。", literal: "The Emperor said to Bearer of the Gilded Mace Kou Xun: \"Yingchuan presses close on the capital—it must be settled in good time.", idiomatic: "The Emperor said to Bearer of the Gilded Mace Kou Xun, \"Yingchuan presses close on the capital—it must be settled in good time." },
  { zh: "惟念獨卿能平之耳，從九卿復出以憂國可也！", literal: "I think only you can pacify it—coming forth again from the Nine Ministers to worry for the state is fitting!", idiomatic: "I think only you can pacify it—coming forth again from the Nine Ministers for the state's sake is fitting!\"" },
  { zh: "」對曰：「穎川聞陛下有事隴、蜀，故狂狡乘間相詿誤耳。", literal: "\" He replied: \"Yingchuan heard Your Majesty was occupied with Long and Shu, so the reckless and cunning took advantage of the interval to mislead one another.", idiomatic: "\" He replied, \"Yingchuan heard Your Majesty was occupied with Long and Shu, so the reckless took advantage of the interval to mislead one another." },
  { zh: "如聞乘輿南向，賊必惶怖歸死，臣願執銳前驅。", literal: "If they hear the imperial carriage is heading south, the bandits are certain to be fearful and return to their deaths; your servant wishes to grasp sharp weapons and lead the van.", idiomatic: "If they hear the imperial carriage is heading south, the bandits will be fearful and submit; I wish to take the van with arms in hand.\"" },
  { zh: "」帝從之。", literal: "\" The Emperor followed this.", idiomatic: "\" The Emperor agreed." },
  { zh: "庚申，車駕南征，穎川盜賊悉降。", literal: "On the day gengshen the imperial carriage campaigned south; the Yingchuan bandits all surrendered.", idiomatic: "On the day gengshen the imperial carriage campaigned south and the Yingchuan bandits all surrendered." },
  { zh: "寇恂竟不拜郡，百姓遮道曰：「願從陛下復借寇君一年。", literal: "Kou Xun in the end did not accept the commandery; the common people blocked the road, saying: \"We wish to beg Your Majesty to lend us Lord Kou for one more year.", idiomatic: "Kou Xun in the end did not take the commandery; the common people blocked the road, saying, \"We beg Your Majesty to lend us Lord Kou for one more year.\"" },
  { zh: "」乃留恂長社，鎮撫吏民，受納餘降。", literal: "\" He thereupon kept Xun at Changshe to pacify officials and commoners and receive those still surrendering.", idiomatic: "\" He kept Xun at Changshe to pacify officials and commoners and receive those still surrendering." },
  { zh: "東郡、濟陰盜賊亦起，帝遣李通、王常擊之。", literal: "Bandits in Dong and Jiyin also rose; the Emperor sent Li Tong and Wang Chang to strike them.", idiomatic: "Bandits in Dong and Jiyin also rose; the Emperor sent Li Tong and Wang Chang to strike them." },
  { zh: "以東光侯耿純嘗為東郡太守，威信著於衛地，遣使拜太中大夫，使與大兵會東郡。", literal: "Because Marquis of Dongguang Geng Chun had once been Administrator of Dong and his authority and trust were established in the lands of Wei, the Emperor sent an envoy to appoint him Grand Master of the Palace and had him join the great army at Dong.", idiomatic: "Because Marquis of Dongguang Geng Chun had once been Administrator of Dong and his authority was established in Wei, the Emperor appointed him Grand Master of the Palace and had him join the main army at Dong." },
  { zh: "東郡聞純入界，盜賊九千餘人皆詣純降，大兵不戰而還；", literal: "Dong, hearing Chun had entered its borders, had more than nine thousand bandits all come to Chun to surrender; the great army returned without fighting;", idiomatic: "When Dong heard Chun had entered its borders, more than nine thousand bandits all came to him to surrender; the main army returned without fighting;" },
  { zh: "璽書復以純為東郡太守。", literal: "an imperial letter again made Chun Administrator of Dong.", idiomatic: "an imperial letter again made Chun Administrator of Dong." },
  { zh: "戊寅，車駕還自穎川。", literal: "On the day wuyin the imperial carriage returned from Yingchuan.", idiomatic: "On the day wuyin the imperial carriage returned from Yingchuan." },
  { zh: "2安丘侯張步將妻子逃奔臨淮，與弟弘、藍欲招其故眾，乘船入海。", literal: "2 Marquis of Anqiu Zhang Bu led his wife and children in flight to Linhuai; with his younger brothers Hong and Lan he wished to rally his former host and take ship to sea.", idiomatic: "Marquis of Anqiu Zhang Bu fled with his wife and children to Linhuai; with his younger brothers Hong and Lan he wished to rally his former followers and take ship to sea." },
  { zh: "琅邪太守陳俊追討，斬之。", literal: "Administrator of Langye Chen Jun pursued and attacked and beheaded him.", idiomatic: "Administrator of Langye Chen Jun pursued and beheaded him." },
  { zh: "3冬，十月，丙午，上行幸懷；", literal: "3 In winter, the tenth month, on the day bingwu, the Emperor went in person to favor Huai;", idiomatic: "In winter, the tenth month, on the day bingwu, the Emperor visited Huai;" },
  { zh: "十一月，乙丑，還雒陽。", literal: "in the eleventh month, on the day yichou, he returned to Luoyang.", idiomatic: "in the eleventh month, on the day yichou, he returned to Luoyang." },
  { zh: "4楊廣死，隗囂窮困，其大將王捷別在戎丘，登城呼漢軍曰：「為隗王城守者，皆必死，無二心。", literal: "4 Yang Guang died; Wei Ao was destitute; his great general Wang Jie was separately at Rongqiu, mounted the wall, and called to the Han army: \"All who hold the city for King Wei are certain to die—there is no second thought.", idiomatic: "Yang Guang died; Wei Ao was destitute; his great general Wang Jie was at Rongqiu, mounted the wall, and called to the Han army, \"All who hold the city for King Wei are certain to die—there is no second thought.\"" },
  { zh: "願諸軍亟罷，請自殺以明之。", literal: "I wish the armies to withdraw at once; I request to kill myself to make this clear.", idiomatic: "I beg the armies to withdraw at once; I will kill myself to make this clear.\"" },
  { zh: "」遂自刎死。", literal: "\" He thereupon cut his own throat and died.", idiomatic: "\" He thereupon cut his own throat and died." },
  { zh: "初，帝敕吳漢曰：「諸郡甲卒但坐費糧食，若有逃亡，則沮敗眾心，宜悉罷之。", literal: "Earlier the Emperor had charged Wu Han: \"The armored soldiers of the various commanderies only sit and waste grain; if any flee, they will break the host's hearts—you ought to dismiss them all.", idiomatic: "Earlier the Emperor had charged Wu Han, \"The armored soldiers of the various commanderies only sit and waste grain; if any flee they will break the army's heart—you ought to dismiss them all.\"" },
  { zh: "」漢等貪并力攻囂，遂不能遣，糧食日少，吏士疲役，逃亡者多。", literal: "\" Han and the others, greedy to combine strength and attack Ao, thereupon could not send them away; grain daily grew less, officials and soldiers were worn by labor, and many fled.", idiomatic: "\" Han and the others, greedy to combine strength and attack Ao, could not send them away; grain daily grew less, officials and soldiers were worn by labor, and many fled." },
  { zh: "岑彭壅谷水灌西城，城未沒丈餘。", literal: "Cen Peng dammed the Gu River to flood Xicheng; the city was not yet submerged by more than a zhang.", idiomatic: "Cen Peng dammed the Gu River to flood Xicheng; the water had not yet submerged the city by more than a zhang." },
  { zh: "會王元、行巡、周宗將蜀救兵五千餘人乘高卒至，鼓噪大呼曰：「百萬之眾方至！", literal: "Just then Wang Yuan, Xing Xun, and Zhou Zong led more than five thousand Shu relief troops, taking the heights, suddenly arrived, beat drums and shouted loudly: \"A host of a million is just arriving!", idiomatic: "Just then Wang Yuan, Xing Xun, and Zhou Zong led more than five thousand Shu relief troops down from the heights, beat drums and shouted, \"A host of a million is just arriving!\"" },
  { zh: "」漢軍大驚，未及成陳，元等決圍殊死戰，遂得入城，迎囂歸冀。", literal: "\" The Han army was greatly alarmed, had not yet formed ranks; Yuan and the others broke the encirclement and fought to the death, thereupon were able to enter the city and welcomed Ao back to Ji.", idiomatic: "\" The Han army was greatly alarmed and had not yet formed ranks; Yuan and the others broke the encirclement and fought to the death, entered the city, and welcomed Ao back to Ji." },
  { zh: "吳漢軍食盡，乃燒輜重，引兵下隴，蓋延、耿弇亦相隨而退。", literal: "Wu Han's army's food was exhausted; he thereupon burned the baggage train and led troops down Long; Gai Yan and Geng Yan also followed one another in withdrawal.", idiomatic: "Wu Han's army ran out of food; he burned the baggage train and led troops down Long; Gai Yan and Geng Yan withdrew as well." },
  { zh: "囂出兵尾擊諸營，岑彭為後拒，諸將乃得全軍東歸；", literal: "Ao sent troops to strike the rear of the camps; Cen Peng served as rear guard, and the generals thereupon were able to bring the whole army back east;", idiomatic: "Ao sent troops to strike the rear of the camps; Cen Peng served as rear guard and the generals brought the whole army back east;" },
  { zh: "唯祭遵屯汧不退。", literal: "only Ji Zun, garrisoned at Qian, did not withdraw.", idiomatic: "only Ji Zun, garrisoned at Qian, did not withdraw." },
  { zh: "吳漢等復屯長安，岑彭還津鄉。", literal: "Wu Han and others again encamped at Chang'an; Cen Peng returned to Jinxiang.", idiomatic: "Wu Han and others again encamped at Chang'an; Cen Peng returned to Jinxiang." },
  { zh: "於是安定、北地、天水、隴西復反為囂。", literal: "Thereupon Anding, Beidi, Tianshui, and Longxi again turned rebel for Ao.", idiomatic: "Thereupon Anding, Beidi, Tianshui, and Longxi again rebelled in support of Wei Ao." },
  { zh: "校尉太原溫序為囂將苟宇所獲，宇曉譬數四，欲降之。", literal: "Commandant Wen Xu of Taiyuan was captured by Ao's general Gou Yu; Yu reasoned and exhorted him four times, wishing to make him submit.", idiomatic: "Commandant Wen Xu of Taiyuan was captured by Wei Ao's general Gou Yu; Yu reasoned with him four times, wishing to win his surrender." },
  { zh: "序大怒，叱宇等曰：「虜何敢迫脅漢將！", literal: "Xu was greatly angered and shouted at Yu and the others: \"How dare you barbarians coerce a Han general!", idiomatic: "Xu was greatly angered and shouted at Yu and the others, \"How dare you barbarians coerce a Han general!\"" },
  { zh: "」因以節廝殺數人。", literal: "\" He thereupon with his staff of authority hacked and killed several men.", idiomatic: "\" He thereupon used his staff of authority to hack down and kill several men." },
  { zh: "宇眾爭欲殺之，宇止之曰：「此義士，死節，可賜以劍。", literal: "Yu's host all struggled to kill him; Yu stopped them and said: \"This is a man of righteousness who dies for his integrity—he may be granted a sword.", idiomatic: "Yu's men all clamored to kill him; Yu stopped them and said, \"This is a man of righteousness who dies for his integrity—grant him a sword.\"" },
  { zh: "」序受劍，銜須於口，顧左右曰：「既為賊所殺，無令須汙土！", literal: "\" Xu accepted the sword, held his beard in his mouth, looked to left and right, and said: \"Since I am to be killed by bandits, do not let my beard touch the soil!", idiomatic: "\" Xu accepted the sword, held his beard in his mouth, looked about, and said, \"Since I am to be killed by bandits, do not let my beard touch the soil!\"" },
  { zh: "」遂伏劍而死。", literal: "\" He thereupon fell on the sword and died.", idiomatic: "\" He thereupon fell on the sword and died." },
  { zh: "從事王忠持其喪歸雒陽，詔賜以塚地，拜三子為郎。", literal: "Attendant Wang Zhong bore his coffin back to Luoyang; an edict granted burial ground and appointed his three sons as Gentlemen of the Palace.", idiomatic: "Attendant Wang Zhong bore his coffin back to Luoyang; an edict granted burial ground and appointed his three sons as Gentlemen of the Palace." },
  { zh: "5十二月，高句麗王遣使朝貢，帝復其王號。", literal: "5. In the twelfth month, the king of Gaogouli sent envoys with tribute; the Emperor restored his royal title.", idiomatic: "5. In the twelfth month, the king of Gaogouli sent envoys with tribute; the Emperor restored his royal title." },
  { zh: "6是歲，大水。", literal: "6. This year there was a great flood.", idiomatic: "6. This year there was a great flood." },
  { zh: "1春，正月，穎陽成侯祭遵薨於軍；", literal: "1. In spring, the first month, Marquis Cheng of Yingyang Ji Zun died in the army;", idiomatic: "1. In spring, the first month, Marquis Cheng of Yingyang Ji Zun died in the army;" },
  { zh: "詔馮異並將其營。", literal: "an edict had Feng Yi take command of his camps as well.", idiomatic: "an edict had Feng Yi take command of his camps as well." },
  { zh: "遵為人，廉約小心，克己奉公，賞賜盡與士卒；", literal: "Zun as a man was frugal and cautious, restrained himself and served the public; rewards and gifts he gave entirely to the soldiers;", idiomatic: "Zun was frugal and cautious, restrained himself and served the public, and gave all rewards and gifts to his soldiers;" },
  { zh: "約束嚴整，所在吏民不知有軍。", literal: "his discipline was strict and orderly, and wherever he was officials and people did not know an army was present.", idiomatic: "his discipline was strict and orderly, and wherever he was officials and commoners scarcely knew an army was present." },
  { zh: "取士皆用儒術，對酒設樂，必雅歌投壺。", literal: "in recruiting scholars he used only Confucian learning; when wine was set out with music, he always had elegant songs and pitch-pot.", idiomatic: "in recruiting men he used only Confucian learning; when wine was set out with music, he always had elegant songs and pitch-pot." },
  { zh: "臨終，遺戒薄葬；", literal: "At his end he left instructions for a plain burial;", idiomatic: "At his end he left instructions for a plain burial;" },
  { zh: "問以家事，終無所言。", literal: "asked about household affairs, he finally said nothing.", idiomatic: "asked about household affairs, he finally said nothing." },
  { zh: "帝愍悼之尤甚，遵喪至河南，車駕素服臨之，望哭哀慟；", literal: "The Emperor mourned him with exceptional grief; when Zun's coffin reached Henan the imperial carriage in plain dress came to it, gazed and wept in deep sorrow;", idiomatic: "The Emperor mourned him with exceptional grief; when Zun's coffin reached Henan the sovereign came in plain dress, gazed upon it, and wept in deep sorrow;" },
  { zh: "還，幸城門，閱過喪車，涕泣不能已；", literal: "on returning he visited the city gate, reviewed the passing funeral carriage, and wept without cease;", idiomatic: "on returning he visited the city gate, reviewed the passing funeral carriage, and wept without cease;" },
  { zh: "喪禮成，復親祠以太牢。", literal: "when the funeral rites were completed he again sacrificed in person with the great offering.", idiomatic: "when the funeral rites were completed he again sacrificed in person with the great offering." },
  { zh: "詔大長秋、謁者、河南尹護喪事，大司農給費。", literal: "An edict had the Grand Chamberlain for the Palace, the Usher, and the Intendant of Henan oversee funeral affairs; the Minister of the Imperial Granary supplied expenses.", idiomatic: "An edict had the Grand Chamberlain for the Palace, the Usher, and the Intendant of Henan oversee funeral affairs; the Minister of the Imperial Granary supplied expenses." },
  { zh: "至葬，車駕復臨之；", literal: "At the burial the imperial carriage again came in person;", idiomatic: "At the burial the sovereign again came in person;" },
  { zh: "既葬，又臨其墳，存見夫人、室家。", literal: "after burial he again visited the tomb and inquired after the lady and household.", idiomatic: "after burial he again visited the tomb and inquired after the lady and household." },
  { zh: "其後朝會，帝每歎曰：「安得憂國奉公如祭征虜者乎！", literal: "Afterward at court audiences the Emperor often sighed and said: \"Where can one find another who cares for the state and serves the public like Campaign-against-Barbarians Ji?", idiomatic: "Afterward at court audiences the Emperor often sighed and said, \"Where can one find another who cares for the state and serves the public like Campaign-against-Barbarians Ji?\"" },
  { zh: "」衛尉銚期曰：「陛下至仁，哀念祭遵不已，群臣各懷慚懼。", literal: "\" Commandant of the Guards Nao Qi said: \"Your Majesty is supremely humane and mourns Ji Zun without end; the ministers each harbor shame and fear.", idiomatic: "\" Commandant of the Guards Nao Qi said, \"Your Majesty is supremely humane and mourns Ji Zun without end; the ministers each harbor shame and fear.\"" },
  { zh: "」帝乃止。", literal: "\" The Emperor thereupon stopped.", idiomatic: "\" The Emperor thereupon stopped." },
  { zh: "2隗囂病且餓，餐糗糒，恚憤而卒。", literal: "2. Wei Ao was ill and also starving; he ate dry baked grain, died in rage and resentment.", idiomatic: "2. Wei Ao was ill and starving; he ate dry baked grain, and died in rage and resentment." },
  { zh: "王元、周宗立囂少子純為王，總兵據冀。", literal: "Wang Yuan and Zhou Zong enthroned Ao's youngest son Chun as king, gathered troops, and held Ji.", idiomatic: "Wang Yuan and Zhou Zong enthroned Ao's youngest son Chun as king, gathered troops, and held Ji." },
  { zh: "公孫述遣將趙匡、田弇助純。", literal: "Gongsun Shu sent generals Zhao Kuang and Tian Yan to assist Chun.", idiomatic: "Gongsun Shu sent generals Zhao Kuang and Tian Yan to assist Chun." },
  { zh: "帝使馮異擊之。", literal: "The Emperor sent Feng Yi to attack them.", idiomatic: "The Emperor sent Feng Yi to attack them." },
  { zh: "3公孫述遣其翼江王田戎、大司徒任滿、南郡太守程泛將數萬人下江關，擊破馮駿等軍，遂拔巫及夷道、夷陵，因據荊門、虎牙，橫江水起浮橋、關樓，立欑柱以絕水道，結營跨山以塞陸路，拒漢兵。", literal: "3. Gongsun Shu sent his King of Assisting Jiang Tian Rong, Grand Minister of Education Ren Man, and Administrator of Nanjun Cheng Fan to lead tens of thousands down Jiang Pass, defeated the army of Feng Jun and others, thereupon took Wu and Yidao and Yiling, and thereby held Jingmen and Huya; across the river they raised floating bridges and barrier towers, set piled pillars to cut the water route, joined camps across mountains to block the land road, and resisted Han troops.", idiomatic: "3. Gongsun Shu sent his King of Assisting Jiang Tian Rong, Grand Minister of Education Ren Man, and Administrator of Nanjun Cheng Fan to lead tens of thousands down Jiang Pass, defeated Feng Jun's army, took Wu, Yidao, and Yiling, and held Jingmen and Huya; across the river they raised floating bridges and barrier towers, set piled pillars to block the water route, joined camps across the mountains to block the land road, and resisted Han troops." },
  { zh: "4夏，六月，丙戌，帝幸緱氏，登轘轅。", literal: "4. In summer, the sixth month, on bingxu, the Emperor visited Gou's clan seat and ascended Huanyuan.", idiomatic: "4. In summer, the sixth month, on bingxu, the Emperor visited Gou's clan seat and ascended Huanyuan." },
  { zh: "5吳漢率王常等四將軍兵五萬餘人擊盧芳將賈覽、閔堪於高柳；", literal: "5. Wu Han led Wang Chang and three other generals with more than fifty thousand troops to attack Lu Fang's generals Jia Lan and Min Kan at Gaoliu;", idiomatic: "5. Wu Han led Wang Chang and three other generals with more than fifty thousand troops to attack Lu Fang's generals Jia Lan and Min Kan at Gaoliu;" },
  { zh: "匈奴救之，漢軍不利。", literal: "the Xiongnu rescued them and the Han army fared ill.", idiomatic: "the Xiongnu rescued them and the Han army fared ill." },
  { zh: "於是匈奴轉盛，鈔暴日增。", literal: "Thereupon the Xiongnu grew stronger still, and raiding and violence increased daily.", idiomatic: "Thereupon the Xiongnu grew stronger still, and raiding and violence increased daily." },
  { zh: "詔朱祜屯常山，王常屯涿郡，破奸將軍侯進屯漁陽，以討虜將軍王霸為上谷太守，以備匈奴。", literal: "An edict had Zhu Hu encamp at Changshan, Wang Chang at Zhuo commandery, Break-Treason General Hou Jin at Yuyang, and Demon-Slaying General Wang Ba made Administrator of Shanggu to guard against the Xiongnu.", idiomatic: "An edict had Zhu Hu encamp at Changshan, Wang Chang at Zhuo commandery, Break-Treason General Hou Jin at Yuyang, and Demon-Slaying General Wang Ba made Administrator of Shanggu to guard against the Xiongnu." },
  { zh: "6帝使來歙悉監護諸將屯長安，太中大夫馬援為之副。", literal: "6. The Emperor sent Lai Xi to oversee in full all the generals encamped at Chang'an, with Grand Master of the Palace Ma Yuan as his deputy.", idiomatic: "6. The Emperor sent Lai Xi to oversee in full all the generals encamped at Chang'an, with Grand Master of the Palace Ma Yuan as his deputy." },
  { zh: "歙上書曰：「公孫述以隴西、天水為籓蔽，故得延命假息；", literal: "Xi memorialized: \"Gongsun Shu takes Longxi and Tianshui as screen and shield, and so obtains extended life and borrowed breath;", idiomatic: "Xi memorialized, \"Gongsun Shu takes Longxi and Tianshui as screen and shield, and so obtains extended life and borrowed breath;" },
  { zh: "今二郡平蕩，則述智計窮矣。", literal: "now that the two commanderies are swept level, Shu's stratagems are exhausted.", idiomatic: "now that the two commanderies are swept level, Shu's stratagems are exhausted." },
  { zh: "宜益選兵馬，儲積資糧。", literal: "It is fitting to increase selection of troops and horses and store up provisions and grain.", idiomatic: "It is fitting to increase selection of troops and horses and store up provisions and grain." },
  { zh: "今西州新破，兵人疲饉，若招以財穀，則其眾可集。", literal: "Now the Western Province is newly broken; soldiers and people are weary and hungry—if recruited with wealth and grain, their hosts can be gathered.", idiomatic: "Now the Western Province is newly broken; soldiers and people are weary and hungry—if recruited with wealth and grain, their hosts can be gathered." },
  { zh: "臣知國家所給非一，用度不足，然有不得已也！", literal: "Your servant knows the state's grants are not one alone and expenditures are insufficient, yet there are times when one cannot do otherwise!", idiomatic: "Your servant knows the state's grants are not one alone and expenditures are insufficient, yet there are times when one cannot do otherwise!\"" },
  { zh: "」帝然之。", literal: "\" The Emperor approved it.", idiomatic: "\" The Emperor approved it." },
  { zh: "於是詔於汧積穀六萬斛。", literal: "Thereupon an edict stored grain at Qian to the amount of sixty thousand hu.", idiomatic: "Thereupon an edict stored sixty thousand hu of grain at Qian." },
  { zh: "秋，八月，來歙率馮異等五將軍討隗純於天水。", literal: "In autumn, the eighth month, Lai Xi led Feng Yi and four other generals to campaign against Wei Chun at Tianshui.", idiomatic: "In autumn, the eighth month, Lai Xi led Feng Yi and four other generals to campaign against Wei Chun at Tianshui." },
  { zh: "7驃騎將軍杜茂與賈覽戰於繁畤，茂軍敗績。", literal: "7. Flying-Cavalry General Du Mao fought Jia Lan at Fanzhi; Mao's army suffered a great defeat.", idiomatic: "7. Flying-Cavalry General Du Mao fought Jia Lan at Fanzhi; Mao's army suffered a great defeat." },
  { zh: "8諸羌自王莽末入居塞內，金城屬縣多為所有。", literal: "8. The various Qiang since the end of Wang Mang had entered and dwelt within the passes; many subordinate counties of Jincheng were held by them.", idiomatic: "8. The various Qiang since the end of Wang Mang had entered and dwelt within the passes; many subordinate counties of Jincheng were held by them." },
  { zh: "隗囂不能討，因就慰納，發其眾與漢相拒。", literal: "Wei Ao could not chastise them and thereupon went to comfort and win them, mustering their hosts to resist Han.", idiomatic: "Wei Ao could not chastise them and thereupon went to comfort and win them, mustering their hosts to resist Han." },
  { zh: "司徒掾班彪上言：「今涼州部皆有降羌，羌胡被發左衽，而與漢人雜處，習俗既異，言語不通，數為小吏黠人所見侵奪，窮恚無聊，故致反叛。", literal: "Chancellor's Clerk Ban Biao submitted: \"Now in the Liangzhou circuit there are surrendered Qiang everywhere; Qiang and Hu with hair unbound and garments folded left live mixed with Han people; customs already differ and speech does not connect—they are repeatedly seen by petty clerks and crafty men invaded and stripped, driven to extremity with nowhere to turn, and so they come to rebellion.", idiomatic: "Chancellor's Clerk Ban Biao submitted, \"Now in the Liangzhou circuit there are surrendered Qiang everywhere; Qiang and Hu with hair unbound and garments folded left live mixed with Han people; customs already differ and speech does not connect—they are repeatedly invaded and stripped by petty clerks and crafty men, driven to extremity with nowhere to turn, and so they rebel.\"" },
  { zh: "夫蠻夷寇亂，皆為此也。", literal: "Barbarian raids and disorder are all for this reason.", idiomatic: "Barbarian raids and disorder are all for this reason." },
  { zh: "舊制，益州部置蠻夷騎都尉，幽州部置領烏桓校尉，涼州部置護羌校尉，皆持節領護，治其怨結，歲時巡行，問所疾苦。", literal: "The old system: in the Yizhou circuit was set the Commandant of Barbarian Cavalry; in the Youzhou circuit the Commandant in Charge of the Wuhuan; in the Liangzhou circuit the Protector of the Qiang—all bearing credentials to lead and guard, settling their grievances, and each year touring to ask their hardships.", idiomatic: "The old system placed in the Yizhou circuit the Commandant of Barbarian Cavalry, in the Youzhou circuit the Commandant in Charge of the Wuhuan, and in the Liangzhou circuit the Protector of the Qiang—all bearing credentials to lead and guard, settling their grievances, and each year touring to ask their hardships." },
  { zh: "又數遣使譯，通導動靜，使塞外羌夷為吏耳目，州郡因此可得警備。", literal: "Again envoys and interpreters were repeatedly sent to open and guide news of movement, making Qiang and Yi beyond the passes the eyes and ears of officials, so that provinces and commanderies could thereby obtain warning and preparation.", idiomatic: "Again envoys and interpreters were repeatedly sent to open and guide news of movement, making Qiang and Yi beyond the passes the eyes and ears of officials, so that provinces and commanderies could thereby obtain warning and preparation." },
  { zh: "今宜復如舊，以明威防。", literal: "Now it is fitting to restore it as of old, to display majesty and guard against trouble.", idiomatic: "Now it is fitting to restore it as of old, to display majesty and guard against trouble." },
  { zh: "」帝從之。", literal: "\" The Emperor followed it.", idiomatic: "\" The Emperor followed it." },
  { zh: "以牛邯為護羌校尉。", literal: "Niu Han was made Protector of the Qiang.", idiomatic: "Niu Han was made Protector of the Qiang." },
  { zh: "9盜殺陰貴人母鄧氏及弟訢。", literal: "9. Bandits killed the Honored Lady of Yin Yin Deng and her brother Xin.", idiomatic: "9. Bandits killed the Honored Lady of Yin Yin Deng and her brother Xin." },
  { zh: "帝其傷之，封貴人弟就為宣恩侯，復召就兄侍中興，欲封之，置印綬於前。", literal: "The Emperor was deeply grieved; he enfeoffed the Honored Lady's younger brother Jiu as Marquis of Proclaiming Grace, again summoned Jiu's elder brother, Palace Attendant Xing, wished to enfeoff him, and set seal and cord before him.", idiomatic: "The Emperor was deeply grieved; he enfeoffed the Honored Lady's younger brother Jiu as Marquis of Proclaiming Grace, again summoned Jiu's elder brother, Palace Attendant Xing, wished to enfeoff him, and set seal and cord before him." },
  { zh: "興固讓曰：「臣未有先登陷陣之功，而一家數人，並蒙爵士，令天下觖望，誠所不願！", literal: "Xing firmly declined: \"Your servant has no merit of being first to ascend and break the battle line, yet several in one family all receive noble rank—this makes the realm resentful; it is truly what I do not wish!", idiomatic: "Xing firmly declined, \"Your servant has no merit of being first to ascend and break the battle line, yet several in one family all receive noble rank—this makes the realm resentful; it is truly what I do not wish!\"" },
  { zh: "」帝嘉之，不奪其志。", literal: "\" The Emperor praised him and did not override his intent.", idiomatic: "\" The Emperor praised him and did not override his intent." },
  { zh: "貴人問其故，興曰：「夫外戚家苦不知謙退，嫁女欲配侯王，取婦眄睨公主，愚心實不安也。", literal: "The Honored Lady asked the reason; Xing said: \"The trouble with affinal kin is not knowing humility and withdrawal—marrying a daughter they wish to match with marquises and kings, taking a wife they cast sidelong glances at princesses; this foolish heart is truly uneasy.", idiomatic: "The Honored Lady asked the reason; Xing said, \"The trouble with affinal kin is not knowing humility and withdrawal—marrying a daughter they wish to match with marquises and kings, taking a wife they cast sidelong glances at princesses; this foolish heart is truly uneasy." },
  { zh: "富貴有極，人當知足，誇奢益為觀聽所譏。", literal: "Wealth and honor have their limit; a man ought to know sufficiency—boasting extravagance is further what observers ridicule.", idiomatic: "Wealth and honor have their limit; a man ought to know sufficiency—boasting extravagance is further what observers ridicule." },
  { zh: "」貴人感其言，深自降挹，卒不為宗親求位。", literal: "\" The Honored Lady was moved by his words, deeply lowered and restrained herself, and finally did not seek offices for her kin.", idiomatic: "\" The Honored Lady was moved by his words, deeply lowered and restrained herself, and finally did not seek offices for her kin." },
  { zh: "10帝召寇恂還，以漁陽太守郭人及為潁川太守。", literal: "10. The Emperor summoned Kou Xun back and made Yuyang Administrator Guo Renji Administrator of Yingchuan.", idiomatic: "10. The Emperor summoned Kou Xun back and made Yuyang Administrator Guo Renji Administrator of Yingchuan." },
  { zh: "人及招降山賊趙宏、召吳等數百人，皆遣歸附農；", literal: "Renji summoned and received the surrender of mountain bandits Zhao Hong, Shao Wu, and several hundred others, all sent back to attach to farming;", idiomatic: "Renji summoned and received the surrender of mountain bandits Zhao Hong, Shao Wu, and several hundred others, all sent back to attach to farming;" },
  { zh: "因自劾專命，帝不以咎之。", literal: "he thereupon impeached himself for acting on his own authority; the Emperor did not blame him for it.", idiomatic: "he thereupon impeached himself for acting on his own authority; the Emperor did not blame him for it." },
  { zh: "後宏、吳等黨與聞人及威信，遠自江南，或從幽、冀，不期俱降，駱驛不絕。", literal: "Later Hong, Wu, and their associates, hearing of Renji's prestige and trust, came from afar—from Jiangnan, or from You and Ji—unexpectedly all submitting together, post relays without cease.", idiomatic: "Later Hong, Wu, and their associates, hearing of Renji's prestige and trust, came from afar—from Jiangnan, or from You and Ji—unexpectedly all submitting together, post relays without cease." },
  { zh: "11莎車王康卒，弟賢立，攻殺拘彌、西夜王，而使康兩子王之。", literal: "11. King Kang of Suoche died; his younger brother Xian succeeded, attacked and killed the kings of Jumi and Xiye, and set Kang's two sons to rule them.", idiomatic: "11. King Kang of Suoche died; his younger brother Xian succeeded, attacked and killed the kings of Jumi and Xiye, and set Kang's two sons to rule them." },
  { zh: "1春，正月，吳漢復率捕虜將軍王霸等四將軍六萬人出高柳擊賈覽，匈奴數千騎救之。", literal: "1. In spring, the first month, Wu Han again led Captive-Slayer General Wang Ba and three other generals with sixty thousand men out from Gaoliu to attack Jia Lan; several thousand Xiongnu horsemen rescued him.", idiomatic: "1. In spring, the first month, Wu Han again led Captive-Slayer General Wang Ba and three other generals with sixty thousand men out from Gaoliu to attack Jia Lan; several thousand Xiongnu horsemen rescued him." },
  { zh: "連戰於平城下，破走之。", literal: "They joined battle repeatedly below Pingcheng and routed and drove him off.", idiomatic: "They joined battle repeatedly below Pingcheng and routed and drove him off." },
  { zh: "2夏陽節侯馮異等與趙匡、田弇戰且一年，皆斬之。", literal: "2. Marquis Jie of Xiayang Feng Yi and others fought Zhao Kuang and Tian Yan for nearly a year and beheaded them both.", idiomatic: "2. Marquis Jie of Xiayang Feng Yi and others fought Zhao Kuang and Tian Yan for nearly a year and beheaded them both." },
  { zh: "隗純未下，諸將欲且還休兵，異固持不動，共攻落門，未拔。", literal: "Wei Chun was not yet taken; the generals wished to withdraw for the time being and rest the troops; Yi firmly held and did not move, and together they attacked Luomen but did not take it.", idiomatic: "Wei Chun was not yet taken; the generals wished to withdraw for the time being and rest the troops; Yi firmly held and did not move, and together they attacked Luomen but did not take it." },
  { zh: "夏，異薨於軍。", literal: "In summer Yi died in the army.", idiomatic: "In summer Yi died in the army." },
  { zh: "3秋，八月，己〔卯〕(", literal: "3. In autumn, the eighth month, on ji [mao] (", idiomatic: "3. In autumn, the eighth month, on ji [mao] (" },
  { zh: "亥)", literal: "hai)", idiomatic: "hai)" },
  { zh: "<ref>己〔卯〕(", literal: "<ref>ji [mao] (", idiomatic: "<ref>ji [mao] (" },
  { zh: "亥)", literal: "hai)", idiomatic: "hai)" },
  { zh: "袁《紀》作「己卯」，為初五日，「己亥」為廿五日。", literal: "Yuan Ji's Annals has \"jimao,\" the fifth day of the month; \"jihai\" is the twenty-fifth.", idiomatic: "Yuan Ji's Annals has \"jimao,\" the fifth day of the month; \"jihai\" is the twenty-fifth." },
  { zh: "若作「己亥」，則與下文干支「戊戌」不合，據改。", literal: "If written as \"jihai,\" it would not agree with the sexagenary day \"wuxu\" below—emended accordingly.", idiomatic: "If written as \"jihai,\" it would not agree with the sexagenary day \"wuxu\" below—emended accordingly." },
  { zh: "</ref>，上幸長安。", literal: "</ref>, the sovereign visited Chang'an.", idiomatic: "</ref>, the sovereign visited Chang'an." },
  { zh: "4初，隗囂將安定高峻擁兵據高平第一，建威大將軍耿弇等圍之，一歲不拔。", literal: "4. Earlier, Wei Ao's general Gao Jun of Anding held troops and occupied Gaoping the First; Establishing Might Great General Geng Yan and others besieged it a full year without taking it.", idiomatic: "4. Earlier, Wei Ao's general Gao Jun of Anding held troops and occupied Gaoping the First; Establishing Might Great General Geng Yan and others besieged it a full year without taking it." },
  { zh: "帝自將征之，寇恂諫曰：「長安道裡居中，應接近便，安定、隴西必懷震懼；", literal: "The Emperor led the campaign in person; Kou Xun remonstrated: \"Chang'an's roads and distance are central—responses are near and convenient; Anding and Longxi will surely harbor shock and fear;", idiomatic: "The Emperor led the campaign in person; Kou Xun remonstrated, \"Chang'an's roads and distance are central—responses are near and convenient; Anding and Longxi will surely harbor shock and fear;" },
  { zh: "此從容一處，可以制四方也。", literal: "this is one place of ease from which the four quarters may be controlled.", idiomatic: "this is one place of ease from which the four quarters may be controlled." },
  { zh: "今士馬疲倦，方履險阻，非萬乘之固也。", literal: "Now soldiers and horses are weary and you are just treading perilous passes—it is not the security of the imperial chariot.", idiomatic: "Now soldiers and horses are weary and you are just treading perilous passes—it is not the security of the imperial chariot." },
  { zh: "前年潁川，可為至戒。", literal: "The affair at Yingchuan two years ago may serve as the utmost warning.", idiomatic: "The affair at Yingchuan two years ago may serve as the utmost warning." },
  { zh: "」帝不從，〔戊戌〕，進幸汧<ref>〔戊戌〕進幸汧章校「十二行本『進』上有『戊戌』二字；", literal: "\" The Emperor did not follow; [on wuxu] he advanced in person to Qian<ref>[On wuxu] advanced in person to Qian—Zhang's collation: \"In the twelve-line edition above 'advance' are the two characters 'wuxu';\"", idiomatic: "\" The Emperor did not follow; [on wuxu] he advanced in person to Qian<ref>[On wuxu] advanced in person to Qian: Zhang's collation—the twelve-line edition has the two characters \"wuxu\" above \"advance\";" },
  { zh: "乙十一行本同；", literal: "the Yi eleven-line edition agrees;", idiomatic: "the Yi eleven-line edition agrees;" },
  { zh: "孔本同；", literal: "Kong's edition agrees;", idiomatic: "Kong's edition agrees;" },
  { zh: "張校同。", literal: "Zhang's collation agrees.", idiomatic: "Zhang's collation agrees." },
  { zh: "」為廿四日，據補，與上文干支「己卯」相合。", literal: "\" It is the twenty-fourth day—supplied on that authority, agreeing with the sexagenary day \"jimao\" above.", idiomatic: "\" It is the twenty-fourth day—supplied on that authority, agreeing with the sexagenary day \"jimao\" above." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "峻猶不下，帝遣寇恂往降之。", literal: "Jun still did not submit; the Emperor sent Kou Xun to go and receive his surrender.", idiomatic: "Jun still did not submit; the Emperor sent Kou Xun to go and receive his surrender." },
  { zh: "恂奉璽書至第一，峻遣軍師皇甫文出謁，辭禮不屈；", literal: "Xun bore the imperial letter on jade to the First; Jun sent his Military Adviser Huangfu Wen out to call on him, but in words and ceremony he would not yield;", idiomatic: "Xun bore the imperial letter on jade to the First; Jun sent his Military Adviser Huangfu Wen out to call on him, but in words and ceremony he would not yield;" },
  { zh: "恂怒，將誅之。", literal: "Xun was angered and was about to execute him.", idiomatic: "Xun was angered and was about to execute him." },
  { zh: "諸將諫曰：「高峻精兵萬人，率多強弩，西遮隴道，連年不下，今欲降之而反戮其使，無乃不可乎？", literal: "The generals remonstrated: \"Gao Jun has elite troops of ten thousand, mostly strong crossbows; he blocks the Long road in the west and for successive years has not been taken—now you wish to receive his surrender yet instead kill his envoy—is this not inadmissible?", idiomatic: "The generals remonstrated, \"Gao Jun has elite troops of ten thousand, mostly strong crossbows; he blocks the Long road in the west and for successive years has not been taken—now you wish to receive his surrender yet instead kill his envoy—is this not inadmissible?\"" },
  { zh: "」恂不應，遂斬之，遣其副歸告峻曰：「軍師無禮，已戮之矣！", literal: "\" Xun did not reply, thereupon beheaded him, and sent his deputy back to tell Jun: \"The Military Adviser was without courtesy—I have already executed him!", idiomatic: "\" Xun did not reply, thereupon beheaded him, and sent his deputy back to tell Jun, \"The Military Adviser was without courtesy—I have already executed him!\"" },
  { zh: "欲降，急降；", literal: "If you wish to submit, submit quickly;", idiomatic: "If you wish to submit, submit quickly;" },
  { zh: "不欲，固守！", literal: "if not, hold firm!", idiomatic: "if not, hold firm!" },
  { zh: "」峻惶恐，即日開城門降。", literal: "\" Jun was terrified and that very day opened the city gate and submitted.", idiomatic: "\" Jun was terrified and that very day opened the city gate and submitted." },
  { zh: "諸將皆賀，因曰：「敢問殺其使而降其城，何也？", literal: "The generals all congratulated him and thereupon said: \"We venture to ask—killing his envoy yet receiving the surrender of his city—how is this?", idiomatic: "The generals all congratulated him and thereupon said, \"We venture to ask—killing his envoy yet receiving the surrender of his city—how is this?\"" },
  { zh: "」恂曰：「皇甫文，峻之腹心，其所取計者也。", literal: "\" Kou Xun said: \"Huangfu Wen is Jun's trusted inner man—the one from whom he takes his plans.", idiomatic: "Kou Xun said, \"Huangfu Wen is Gao Jun's trusted inner counselor—the one from whom he takes his plans." },
  { zh: "今來，辭意不屈，必無降心。", literal: "Now he has come with language and intent unyielding; he surely has no heart to surrender.", idiomatic: "Now he has come with language and intent unyielding; he surely has no heart to surrender." },
  { zh: "全之則文得其計，殺之則峻亡其膽，是以降耳。", literal: "If we spare him, Wen gets his plan across; if we kill him, Jun loses his courage—that is why he surrendered.", idiomatic: "If we spare him, Wen gets his plan across; if we kill him, Gao Jun loses his courage—that is why he surrendered." },
  { zh: "」諸將皆曰：「非所及也！", literal: "\" The generals all said: \"Beyond what we could reach!", idiomatic: "The generals all said, \"Beyond what we could reach!\"" },
  { zh: "5冬，十月，來歙與諸將攻破落門，周宗、行巡、苟宇、趙恢等將隗純降，王元奔蜀。", literal: "5 Winter, tenth month, Lai Xi with the generals broke Luomen; Zhou Zong, Xing Xun, Gou Yu, Zhao Hui, and others led Wei Chun to surrender; Wang Yuan fled to Shu.", idiomatic: "In the fifth year, in winter, in the tenth month, Lai Xi and the generals broke Luomen; Zhou Zong, Xing Xun, Gou Yu, Zhao Hui, and others led Wei Chun to surrender; Wang Yuan fled to Shu." },
  { zh: "徙諸隗於京師以東。", literal: "The various Wei clansmen were moved east of the capital.", idiomatic: "The various Wei clansmen were relocated east of the capital." },
  { zh: "後隗純與賓客亡入胡，至武威，捕得，誅之。", literal: "Later Wei Chun with his guests fled into the Hu lands; reaching Wuwei they were captured and executed.", idiomatic: "Later Wei Chun fled into the barbarian lands with his guests; reaching Wuwei they were captured and executed." },
  { zh: "6先零羌與諸種寇金城、隴西，來歙率蓋延等進擊，大破之，斬首虜數千人。", literal: "6 The Xianling Qiang with various tribes raided Jincheng and Longxi; Lai Xi led Gai Yan and others forward to strike, routed them greatly, and beheaded and captured several thousand.", idiomatic: "In the sixth year the Xianling Qiang and various tribes raided Jincheng and Longxi; Lai Xi led Gai Yan and others in attack, routed them completely, and beheaded and captured several thousand." },
  { zh: "於是開倉稟以賑饑乏，隴右遂安，而涼州流通焉。", literal: "Thereupon they opened granaries and distributed grain to relieve hunger and want; Longyou was thereby pacified, and Liangzhou commerce flowed again.", idiomatic: "Thereupon they opened granaries and distributed grain to relieve hunger and want; Longyou was thereby pacified, and commerce in Liangzhou flowed again." },
  { zh: "7庚寅，車駕還宮。", literal: "7 Day gengyin, the imperial carriage returned to the palace.", idiomatic: "In the seventh year, on the day gengyin, the imperial carriage returned to the palace." },
  { zh: "1春，三月，己酉，帝幸南陽，還幸章陵；", literal: "1 Spring, third month, day jiyou, the Emperor visited Nanyang and then visited Zhangling;", idiomatic: "In the first year, in spring, in the third month, on the day jiyou, the Emperor visited Nanyang and then visited Zhangling;" },
  { zh: "庚午，車駕還宮。", literal: "Day gengwu, the imperial carriage returned to the palace.", idiomatic: "On the day gengwu, the imperial carriage returned to the palace." },
  { zh: "2岑彭屯津鄉，數攻田戎等，不克。", literal: "2 Cen Peng encamped at Jinxiang, repeatedly attacked Tian Rong and others, and could not overcome them.", idiomatic: "In the second year Cen Peng encamped at Jinxiang, repeatedly attacked Tian Rong and others, and could not overcome them." },
  { zh: "帝遣吳漢率誅虜將軍劉隆等三將，發荊州兵凡六萬餘人、騎五千匹，與彭會荊門。", literal: "The Emperor sent Wu Han leading three generals including Executioner of Captives General Liu Long, mobilizing Jing province troops totaling more than sixty thousand men and five thousand horses, to join Peng at Jingmen.", idiomatic: "The Emperor sent Wu Han leading three generals including Executioner of Captives General Liu Long, mobilizing more than sixty thousand troops and five thousand horses from Jing province, to join Peng at Jingmen." },
  { zh: "彭裝戰船數〔十〕(", literal: "Peng fitted out war ships numbering [several tens](", idiomatic: "Peng fitted out war ships numbering [several tens](" },
  { zh: "千)", literal: "thousand)", idiomatic: "thousand)" },
  { zh: "艘<ref>彭裝戰船數〔十〕(", literal: "vessels<ref>Peng fitted out war ships numbering [several tens](", idiomatic: "vessels<ref>Peng fitted out war ships numbering [several tens](" },
  { zh: "千)", literal: "thousand)", idiomatic: "thousand)" },
  { zh: "艘章校「十二行本『千』作『十』；", literal: "vessels—Zhang's collation: \"In the twelve-line edition 'thousand' reads 'ten';\"", idiomatic: "vessels—Zhang's collation: \"In the twelve-line edition 'thousand' reads 'ten';\"" },
  { zh: "乙十一行本同。", literal: "the yi eleven-line edition agrees.", idiomatic: "the yi eleven-line edition agrees." },
  { zh: "」作「千」太多，據改。", literal: "\" Reading 'thousand' is too many; emended accordingly.", idiomatic: "\" Reading 'thousand' is too many; emended accordingly." },
  { zh: "</ref>，吳漢以諸郡棹卒多費糧穀，欲罷之。", literal: "</ref>; Wu Han, because the oarsmen from the various commanderies consumed much grain, wished to dismiss them.", idiomatic: "</ref>; Wu Han, because the oarsmen from the various commanderies consumed much grain, wished to dismiss them." },
  { zh: "彭以為蜀兵盛，不可遣，上書言狀。", literal: "Peng held that Shu troops were numerous and they could not be sent away; he submitted a memorial stating the situation.", idiomatic: "Peng held that Shu troops were numerous and they could not be sent away; he submitted a memorial stating the situation." },
  { zh: "帝報彭曰：「大司馬習用步騎，不曉水戰，荊門之事，一由征南公為重而已。", literal: "The Emperor replied to Peng: \"The Grand Marshal is practiced in infantry and cavalry and does not understand naval warfare; as for the Jingmen affair, it all rests on the Marquis Who Pacifies the South alone.", idiomatic: "The Emperor replied to Peng, \"The Grand Marshal is practiced in infantry and cavalry and does not understand naval warfare; as for the Jingmen affair, it all rests on the Marquis Who Pacifies the South alone.\"" },
  { zh: "閏月，岑彭令軍中募攻浮橋，先登者上賞。", literal: "Intercalary month: Cen Peng ordered the army to recruit men to assault the floating bridge; those who scaled first received top reward.", idiomatic: "In the intercalary month Cen Peng ordered the army to recruit men to assault the floating bridge; those who scaled first received top reward." },
  { zh: "於是偏將軍魯奇應募而前，時東風狂急，魯奇船逆流而上，直衝浮橋，而欑柱有反杷鉤，奇船不得去。", literal: "Thereupon Colonel Lu Qi volunteered and went forward; an east wind blew wild and fierce; Lu Qi's boat went up against the current straight at the floating bridge, but the piles had reverse rake hooks—Qi's boat could not get free.", idiomatic: "Thereupon Colonel Lu Qi volunteered and went forward; an east wind blew wild and fierce; Lu Qi's boat went up against the current straight at the floating bridge, but the piles had reverse rake hooks and Qi's boat could not get free." },
  { zh: "奇等乘勢殊死戰，因飛炬焚之，風怒火盛，橋樓崩燒。", literal: "Qi and the others seized the momentum and fought to the death; they then hurled fire torches to burn it; wind fed the flames until they were fierce—the bridge towers collapsed in fire.", idiomatic: "Qi and the others seized the momentum and fought to the death; they hurled fire torches to burn it; wind fed the flames until they were fierce and the bridge towers collapsed in fire." },
  { zh: "岑彭悉軍順風並進，所向無前，蜀兵大亂，溺死者數千人，斬任滿，生獲程汎，而田戎走保江州。", literal: "Cen Peng led the whole army with the wind in parallel advance, unstoppable wherever they went; Shu troops fell into great disorder; several thousand drowned; Ren Man was beheaded, Cheng Fan captured alive, and Tian Rong fled to hold Jiangzhou.", idiomatic: "Cen Peng led the whole army with the wind in parallel advance, unstoppable wherever they went; Shu troops fell into great disorder; several thousand drowned; Ren Man was beheaded, Cheng Fan was captured alive, and Tian Rong fled to hold Jiangzhou." },
  { zh: "彭上劉隆為南郡太守；", literal: "Peng recommended Liu Long as Administrator of Nan commandery;", idiomatic: "Peng recommended Liu Long as Administrator of Nan commandery;" },
  { zh: "自率輔威將軍臧宮、驍騎將軍劉歆長驅入江關。", literal: "himself led Auxiliary Majestic General Zang Gong and Valiant Cavalry General Liu Xin in a long drive into the Jiang Pass.", idiomatic: "himself led Auxiliary Majestic General Zang Gong and Valiant Cavalry General Liu Xin in a long drive into the Jiang Pass." },
  { zh: "令軍中無得虜掠，所過，百姓皆奉牛酒迎勞，彭復讓不受。", literal: "He ordered that within the army there was to be no seizing plunder; wherever they passed the common people all offered oxen and wine to welcome and refresh them—Peng again declined and would not accept.", idiomatic: "He ordered that within the army there was to be no seizing plunder; wherever they passed the common people all offered oxen and wine to welcome and refresh them, but Peng again declined and would not accept." },
  { zh: "百姓大喜，爭開門降。", literal: "The common people were greatly pleased and vied to open their gates and surrender.", idiomatic: "The common people were greatly pleased and vied to open their gates and surrender." },
  { zh: "詔彭守益州牧，所下郡輒行太守事，彭若出界，即以太守號付後將軍。", literal: "An edict made Peng acting Governor of Yizhou; in each commandery he reached he at once exercised the Administrator's duties; if Peng crossed the border, the title of Administrator was handed to the Rear General.", idiomatic: "An edict made Peng acting Governor of Yizhou; in each commandery he reached he at once exercised the Administrator's duties; if Peng crossed the border, the title of Administrator was handed to the Rear General." },
  { zh: "選官屬守州中長吏。", literal: "He selected officials and staff to hold the long-term offices within the province.", idiomatic: "He selected officials and staff to hold the long-term offices within the province." },
  { zh: "彭到江州，以其城固糧多，難卒拔，留馮駿守之；", literal: "Peng reached Jiangzhou; because its walls were strong and grain abundant and it could not quickly be taken, he left Feng Jun to hold it;", idiomatic: "Peng reached Jiangzhou; because its walls were strong and grain abundant and it could not quickly be taken, he left Feng Jun to hold it;" },
  { zh: "自引兵乘利直指墊江，攻破平曲，收其米數十萬石。", literal: "himself led troops, seizing advantage, straight at Dianjiang, broke Pingqu, and gathered several hundred thousand shi of rice.", idiomatic: "himself led troops, seizing advantage, straight at Dianjiang, broke Pingqu, and gathered several hundred thousand shi of rice." },
  { zh: "吳漢留夷陵，裝露橈繼進。", literal: "Wu Han remained at Yiling, fitting out uncovered oars and continuing forward.", idiomatic: "Wu Han remained at Yiling, fitting out uncovered oars and continuing forward." },
  { zh: "3夏，先零羌寇臨洮。", literal: "3 Summer, the Xianling Qiang raided Lintao.", idiomatic: "In the third year, in summer, the Xianling Qiang raided Lintao." },
  { zh: "來歙薦馬援為隴西太守，擊先零羌，大破之。", literal: "Lai Xi recommended Ma Yuan as Administrator of Longxi; he struck the Xianling Qiang and routed them greatly.", idiomatic: "Lai Xi recommended Ma Yuan as Administrator of Longxi; he struck the Xianling Qiang and routed them completely." },
  { zh: "4公孫述以王元為將軍，使與領軍環安拒河池。", literal: "4 Gongsun Shu made Wang Yuan a general and sent him with Colonel of the Guard Huan An to hold Hechi.", idiomatic: "In the fourth year Gongsun Shu made Wang Yuan a general and sent him with Colonel of the Guard Huan An to hold Hechi." },
  { zh: "六月，來歙與蓋延等進攻元、安，大破之，遂克下辨，乘勝遂進。", literal: "Sixth month, Lai Xi with Gai Yan and others advanced to attack Yuan and An, routed them greatly, then took Xiabian and pressed the victory forward.", idiomatic: "In the sixth month Lai Xi with Gai Yan and others advanced to attack Yuan and An, routed them completely, then took Xiabian and pressed the victory forward." },
  { zh: "蜀人大懼，使刺客刺歙，未殊，馳召蓋延。", literal: "Shu people were greatly afraid and sent assassins to stab Xi; he was not yet dead and urgently summoned Gai Yan.", idiomatic: "The people of Shu were greatly afraid and sent assassins to stab Lai Xi; he was not yet dead and urgently summoned Gai Yan." },
  { zh: "延見歙，因伏悲哀，不能仰視。", literal: "Yan saw Xi and thereupon prostrated himself in grief, unable to look up.", idiomatic: "Yan saw Xi and thereupon prostrated himself in grief, unable to look up." },
  { zh: "歙叱延曰：「虎牙何敢然！", literal: "Xi rebuked Yan: \"Tiger's Tooth, how dare you act thus!", idiomatic: "Xi rebuked Yan, \"Tiger's Tooth, how dare you act thus!" },
  { zh: "今使者中刺客，無以報國，故呼巨卿，欲相屬以軍事，而反效兒女子涕泣乎！", literal: "Now the envoy has been struck by assassins and cannot repay the state—therefore I called Great Qing, wishing to entrust you with military affairs, yet you instead imitate children and women in weeping!", idiomatic: "Now the envoy has been struck by assassins and cannot repay the state—therefore I called you, Great Qing, wishing to entrust you with military affairs, yet you instead imitate children and women in weeping!" },
  { zh: "刃雖在身，不能勒兵斬公邪？", literal: "Though the blade is in my body, can you not muster troops and behead the lord?", idiomatic: "Though the blade is in my body, can you not muster troops and behead the enemy lord?\"" },
  { zh: "」延收淚強起，受所誡。", literal: "\" Yan wiped his tears, forced himself to rise, and received the charge given him.", idiomatic: "Yan wiped his tears, forced himself to rise, and received the charge given him." },
  { zh: "歙自書表曰：「臣夜人定後，為何人所賊傷，中臣要害。", literal: "Xi himself wrote a memorial saying: \"Your servant, after men had settled at night, was wounded by assassins—struck in my vital place.", idiomatic: "Xi himself wrote a memorial, saying, \"Your servant, after men had settled at night, was wounded by assassins—struck in my vital place." },
  { zh: "臣不敢自惜，誠恨奉職不稱，以為朝廷羞。", literal: "Your servant dares not spare himself but truly regrets that in fulfilling duty I have not measured up, bringing shame on the court.", idiomatic: "Your servant dares not spare himself but truly regrets that in fulfilling duty I have not measured up, bringing shame on the court." },
  { zh: "夫理國以得賢為本，太中大夫段襄，骨鯁可任，願陛下裁察。", literal: "To order a state, gaining the worthy is fundamental; Grand Master of the Palace Duan Xiang is a backbone who can be entrusted—may Your Majesty judge and examine.", idiomatic: "To order a state, gaining the worthy is fundamental; Grand Master of the Palace Duan Xiang is a backbone who can be entrusted—may Your Majesty judge and examine." },
  { zh: "又臣兄弟不肖，終恐被罪，陛下哀憐，數賜教督。", literal: "Moreover your servant's brothers are unworthy and in the end will surely incur guilt—may Your Majesty pity and repeatedly grant instruction and oversight.", idiomatic: "Moreover your servant's brothers are unworthy and in the end will surely incur guilt—may Your Majesty pity them and repeatedly grant instruction and oversight." },
  { zh: "」投筆抽刃而絕。", literal: "\" He cast down the brush, drew out the blade, and expired.", idiomatic: "He cast down the brush, drew out the blade, and expired." },
  { zh: "帝聞，大驚，省書攬涕。", literal: "The Emperor heard, was greatly startled, read the memorial, and clasped it while weeping.", idiomatic: "The Emperor heard, was greatly startled, read the memorial, and wept as he clasped it." },
  { zh: "以揚武將軍馬成守中郎將代之。", literal: "He made Valiant Martial General Ma Cheng hold the post of Colonel of the Palace Guard in his stead.", idiomatic: "He made Valiant Martial General Ma Cheng hold the post of Colonel of the Palace Guard in his stead." },
  { zh: "歙喪還洛陽，乘輿縞素臨吊、送葬。", literal: "When Xi's funeral returned to Luoyang, the imperial carriage in unbleached silk came to mourn and escort the burial.", idiomatic: "When Xi's funeral returned to Luoyang, the Emperor in unbleached silk came to mourn and escort the burial." },
  { zh: "5趙王良從帝送歙喪還，入夏城門，與中郎將張邯爭道，叱邯旋車，又詰責門候，使前走數十步。", literal: "5 King Zhao Liang followed the Emperor escorting Xi's funeral back; entering the Xia city gate he disputed the road with Colonel of the Palace Guard Zhang Han, rebuked Han to turn his carriage, and also reproached the gate warden, making him go forward several tens of paces.", idiomatic: "In the fifth year King Zhao Liang followed the Emperor escorting Xi's funeral back; entering the Xia city gate he disputed the road with Colonel of the Palace Guard Zhang Han, rebuked Han to turn his carriage, and also reproached the gate warden, making him go forward several tens of paces." },
  { zh: "司隸校尉鮑永劾奏：「良無籓臣禮，大不敬。", literal: "Director of the Secretariat Bao Yong impeached him: \"Liang lacks the rites of a feudatory minister—great irreverence.", idiomatic: "Director of the Secretariat Bao Yong impeached him, saying, \"Liang lacks the rites of a feudatory minister—great irreverence.\"" },
  { zh: "」良尊戚貴重，而永劾之，朝廷肅然。", literal: "\" Liang was a honored kinsman of weighty rank, yet Yong impeached him—the court was awed into order.", idiomatic: "Liang was an honored kinsman of weighty rank, yet Bao Yong impeached him—the court was awed into order." },
  { zh: "永辟扶風鮑恢為都官從事，恢亦抗直，不避強禦。", literal: "Yong recruited Bao Hui of Fufeng as Director of Capital Cases; Hui was also upright and unyielding, not avoiding the powerful.", idiomatic: "Bao Yong recruited Bao Hui of Fufeng as Director of Capital Cases; Hui was also upright and unyielding and did not avoid the powerful." },
  { zh: "帝常曰：「貴戚且斂手以避二鮑。", literal: "The Emperor often said: \"Even the honored kin fold their hands to avoid the two Baos.", idiomatic: "The Emperor often said, \"Even the honored kin fold their hands to avoid the two Baos.\"" },
  { zh: "」永行縣到霸陵，路經更始墓，下拜，哭盡哀而去，西至扶風，椎牛上苟諫塚。", literal: "\" Yong on circuit reached Baling; the road passed Gengshi's tomb—he dismounted, bowed, wept his full grief, and departed; west to Fufeng he beat an ox as offering atop Gou Jian's mound.", idiomatic: "Bao Yong on circuit reached Baling; the road passed Gengshi's tomb—he dismounted, bowed, wept his full grief, and departed; west to Fufeng he beat an ox as offering atop Gou Jian's mound." },
  { zh: "帝聞之，意不平，問公卿曰：「奉使如此，何如？", literal: "The Emperor heard and was ill at ease; he asked the high ministers: \"To go on commission like this—how is it?", idiomatic: "The Emperor heard and was ill at ease; he asked the high ministers, \"To go on commission like this—how is it?\"" },
  { zh: "」太中大夫張湛對曰：「仁者，行之宗；", literal: "\" Grand Master of the Palace Zhang Zhan replied: \"Benevolence is the ancestor of conduct;", idiomatic: "Grand Master of the Palace Zhang Zhan replied, \"Benevolence is the ancestor of conduct;" },
  { zh: "忠者，義之主也。", literal: "loyalty is the master of righteousness.", idiomatic: "loyalty is the master of righteousness." },
  { zh: "仁不遺舊，忠不忘君，行之高者也。", literal: "Benevolence does not abandon the old; loyalty does not forget the lord—these are the heights of conduct.", idiomatic: "Benevolence does not abandon the old; loyalty does not forget the lord—these are the heights of conduct.\"" },
  { zh: "」帝意乃釋。", literal: "\" The Emperor's mind was then released.", idiomatic: "The Emperor's mind was then released." },
  { zh: "6帝自將征公孫述；", literal: "6 The Emperor himself led the campaign against Gongsun Shu;", idiomatic: "In the sixth year the Emperor himself led the campaign against Gongsun Shu;" },
  { zh: "秋，七月，次長安。", literal: "autumn, seventh month, he halted at Chang'an.", idiomatic: "in autumn, in the seventh month, he halted at Chang'an." },
  { zh: "7公孫述使其將延岑、呂鮪、王元、公孫恢悉兵拒廣漢及資中，又遣將侯丹率二萬餘人拒黃石。", literal: "7 Gongsun Shu sent his generals Yan Cen, Lü Fu, Wang Yuan, and Gongsun Hui with all their troops to hold Guanghan and Zizhong, and also sent General Hou Dan leading more than twenty thousand men to hold Huangshi.", idiomatic: "In the seventh year Gongsun Shu sent his generals Yan Cen, Lü Fu, Wang Yuan, and Gongsun Hui with all their troops to hold Guanghan and Zizhong, and also sent General Hou Dan with more than twenty thousand men to hold Huangshi." },
  { zh: "岑彭使臧宮將降卒五萬，從涪水上平曲，拒延岑，自分兵浮江下還江州，溯都江而上，襲擊侯丹，大破之；", literal: "Cen Peng sent Zang Gong leading fifty thousand surrendered troops up the Fu River from Pingshui to Pingqu to hold Yan Cen; he himself divided troops to float down the river back to Jiangzhou, go up the Du River, and strike Hou Dan, routing him greatly;", idiomatic: "Cen Peng sent Zang Gong with fifty thousand surrendered troops up the Fu River from Pingshui to Pingqu to hold Yan Cen; he himself divided troops to float down the river back to Jiangzhou, go up the Du River, and strike Hou Dan, routing him completely;" },
  { zh: "因晨夜倍道兼行二千餘里，逕拔武陽。", literal: "then day and night on double marches traveled more than two thousand li and straightway took Wuyang.", idiomatic: "then traveled more than two thousand li day and night on forced marches and straightway took Wuyang." },
  { zh: "使精騎馳擊廣都，去成都數十里，勢若風雨，所至皆奔散。", literal: "He sent elite cavalry to gallop and strike Guangdu, several tens of li from Chengdu; their momentum was like wind and rain—wherever they reached all fled and scattered.", idiomatic: "He sent elite cavalry to gallop and strike Guangdu, several tens of li from Chengdu; their momentum was like wind and rain—wherever they reached all fled and scattered." },
  { zh: "初，述聞漢兵在平曲，故遣大兵逆之。", literal: "At first Shu heard Han troops were at Pingqu and therefore sent a great army to oppose them.", idiomatic: "At first Gongsun Shu heard Han troops were at Pingqu and therefore sent a great army to oppose them." },
  { zh: "及彭至武陽，繞出延岑軍後，蜀地震駭。", literal: "When Peng reached Wuyang and came out behind Yan Cen's army, Shu was shaken as by an earthquake in terror.", idiomatic: "When Peng reached Wuyang and came out behind Yan Cen's army, Shu was shaken as by an earthquake in terror." },
  { zh: "述大驚，以杖擊地曰：「是何神也！", literal: "Shu was greatly startled, struck the ground with his staff, and said: \"What god is this!", idiomatic: "Gongsun Shu was greatly startled, struck the ground with his staff, and said, \"What god is this!\"" },
  { zh: "延岑盛兵於〔沈〕(", literal: "Yan Cen massed troops at [Shen](", idiomatic: "Yan Cen massed troops at [Shen](" },
  { zh: "沅)", literal: "Yuan)", idiomatic: "Yuan)" },
  { zh: "水<ref>延岑盛兵於〔沈〕(", literal: "River<ref>Yan Cen massed troops at [Shen](", idiomatic: "River<ref>Yan Cen massed troops at [Shen](" },
  { zh: "沅)", literal: "Yuan)", idiomatic: "Yuan)" },
  { zh: "水據胡注改。", literal: "River—emended per Hu's annotation.", idiomatic: "River—emended per Hu's annotation." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "臧宮眾多食少，轉輸不至，降者皆欲散畔郡邑，復更保聚，觀望成敗。", literal: "Zang Gong's host was many but food scant; relay transport did not arrive; the surrendered all wished to scatter and rebel against commanderies and counties, again holding together in defense and watching success or failure.", idiomatic: "Zang Gong's host was many but food scant; relay transport did not arrive; the surrendered all wished to scatter and rebel against commanderies and counties, again holding together in defense and watching success or failure." },
  { zh: "宮欲引還，恐為所反；", literal: "Gong wished to draw back but feared being turned on by them;", idiomatic: "Zang Gong wished to draw back but feared being turned on by them;" },
  { zh: "會帝遣謁者將兵詣岑彭，有馬七百匹，宮矯制取以自益，晨夜進兵，多張旗幟，登山鼓噪，右步左騎，挾船而引，呼聲動山谷。", literal: "it happened the Emperor sent a Herald leading troops to Cen Peng with seven hundred horses; Gong forged an order and took them to enrich himself, advanced troops day and night, set out many banners and flags, climbed mountains beating drums and shouting, infantry on the right and cavalry on the left, drawing boats along—cries shook the valleys.", idiomatic: "it happened the Emperor sent a Herald leading troops to Cen Peng with seven hundred horses; Zang Gong forged an order and took them to enrich himself, advanced troops day and night, set out many banners and flags, climbed mountains beating drums and shouting, infantry on the right and cavalry on the left, drawing boats along—cries shook the valleys." },
  { zh: "岑不意漢軍卒至，登山望之，大震恐；", literal: "Cen did not expect Han troops to arrive so suddenly; climbing the mountain to look, he was greatly shaken in terror;", idiomatic: "Yan Cen did not expect Han troops to arrive so suddenly; climbing the mountain to look, he was greatly shaken in terror;" },
  { zh: "宮因縱擊，大破之，斬首、溺死者萬餘人，水為之濁。", literal: "Gong thereupon loosed the attack and routed them greatly; beheaded and drowned were more than ten thousand men—the water was muddied thereby.", idiomatic: "Zang Gong thereupon loosed the attack and routed them completely; more than ten thousand were beheaded or drowned—the water was muddied thereby." },
  { zh: "延岑奔成都，其眾悉降，盡獲其兵馬珍寶。", literal: "Yan Cen fled to Chengdu; his host all surrendered; they fully gained his troops, horses, and treasures.", idiomatic: "Yan Cen fled to Chengdu; his host all surrendered; they fully gained his troops, horses, and treasures." },
  { zh: "自是乘勝追北，降者以十萬數。", literal: "From this they rode victory in pursuit north; those who surrendered numbered in the hundreds of thousands.", idiomatic: "From this they rode victory in pursuit north; those who surrendered numbered in the hundreds of thousands." },
  { zh: "軍至〔平〕陽鄉<ref>軍至〔平〕陽鄉據胡注補。", literal: "The army reached [Ping]yang village<ref>The army reached [Ping]yang village—supplemented per Hu's annotation.", idiomatic: "The army reached [Ping]yang village<ref>The army reached [Ping]yang village—supplemented per Hu's annotation." },
  { zh: "</ref>，王元舉眾降。", literal: "</ref>; Wang Yuan led his host to surrender.", idiomatic: "</ref>; Wang Yuan led his host to surrender." },
  { zh: "帝與公孫述書，陳言禍福，示以丹青之信。", literal: "The Emperor wrote to Gongsun Shu, setting forth fortune and calamity, showing the good faith of cinnabar and green.", idiomatic: "The Emperor wrote to Gongsun Shu, setting forth fortune and calamity, showing the good faith of cinnabar and green." },
  { zh: "述省書歎息，以示所親。", literal: "Shu read the letter and sighed, showing it to those close to him.", idiomatic: "Gongsun Shu read the letter and sighed, showing it to those close to him." },
  { zh: "太常常少、光祿勳張隆皆勸述降。", literal: "Grand Master of Ceremonies Chang Shao and Household Minister Zhang Long all urged Shu to surrender.", idiomatic: "Grand Master of Ceremonies Chang Shao and Household Minister Zhang Long all urged Gongsun Shu to surrender." },
  { zh: "述曰：「廢興，命也，豈有降天子哉！", literal: "Shu said: \"Rise and fall are fate—how could there be a Son of Heaven who surrenders!", idiomatic: "Gongsun Shu said, \"Rise and fall are fate—how could there be a Son of Heaven who surrenders!\"" },
  { zh: "」左右莫敢復言。", literal: "\" Those at his side dared speak no more.", idiomatic: "Those at his side dared speak no more." },
  { zh: "少、隆皆以憂死。", literal: "Shao and Long both died of grief.", idiomatic: "Chang Shao and Zhang Long both died of grief." },
  { zh: "8帝還自長安。", literal: "8 The Emperor returned from Chang'an.", idiomatic: "In the eighth year the Emperor returned from Chang'an." },
  { zh: "9冬，十月，公孫述使刺客詐為亡奴，降岑彭，夜，刺殺彭。", literal: "9 Winter, tenth month, Gongsun Shu sent assassins posing as escaped slaves to surrender to Cen Peng; at night they stabbed and killed Peng.", idiomatic: "In the ninth year, in winter, in the tenth month, Gongsun Shu sent assassins posing as escaped slaves to surrender to Cen Peng; at night they stabbed and killed him." },
  { zh: "太中大夫監軍鄭興領其營，以俟吳漢至而授之。", literal: "Grand Master of the Palace supervising the army Zheng Xing took command of his camp to await Wu Han's arrival and hand it over.", idiomatic: "Grand Master of the Palace supervising the army Zheng Xing took command of his camp to await Wu Han's arrival and hand it over." },
  { zh: "彭持軍整齊，秋毫無犯。", literal: "Peng held the army in good order—not the slightest violation.", idiomatic: "Peng held the army in good order—not the slightest violation." },
  { zh: "邛穀王任貴聞彭威信，數千里遣使迎降；", literal: "Qionggu King Ren Gui heard of Peng's prestige and trustworthiness and from several thousand li sent envoys to welcome and surrender;", idiomatic: "Qionggu King Ren Gui heard of Cen Peng's prestige and from several thousand li sent envoys to welcome and surrender;" },
  { zh: "會彭已被害，帝盡以任貴所獻賜彭妻子。", literal: "but Peng had already been killed; the Emperor gave all that Ren Gui had presented to Peng's wife and children.", idiomatic: "But Cen Peng had already been killed; the Emperor gave all that Ren Gui had presented to Cen Peng's wife and children." },
  { zh: "蜀人為立廟祠之。", literal: "The people of Shu built a temple and sacrificed to him.", idiomatic: "The people of Shu built a temple and sacrificed to him." },
  { zh: "10馬成等破河池，遂平武都。", literal: "10. Ma Cheng and others defeated Hechi and thereby pacified Wudu.", idiomatic: "10. Ma Cheng and others defeated Hechi and thereby pacified Wudu." },
  { zh: "先零諸種羌數萬人，屯聚寇鈔，拒浩亹隘。", literal: "Several tens of thousands of Xianliang and various Qiang tribes gathered to plunder and held the Hao'ai Pass.", idiomatic: "Several tens of thousands of Xianliang and various Qiang tribes gathered to plunder and held the Hao'ai Pass." },
  { zh: "成與馬援深入討擊，大破之，徙降羌置天水、隴西、扶風。", literal: "Cheng with Ma Yuan penetrated deep in pursuit and attack, routed them greatly, and relocated the submitted Qiang to Tianshui, Longxi, and Fufeng.", idiomatic: "Ma Cheng with Ma Yuan penetrated deep in pursuit, routed them completely, and relocated the submitted Qiang to Tianshui, Longxi, and Fufeng." },
  { zh: "是時，朝臣以金城破羌之西，塗遠多寇，議欲棄之。", literal: "At this time the court ministers, because west of Jincheng's Poqiang the road was long and bandits many, debated abandoning it.", idiomatic: "At this time the court ministers, because west of Jincheng's Poqiang the road was long and bandits were many, debated abandoning the region." },
  { zh: "馬援上言：「破羌以西，城多完牢，易可依固。", literal: "Ma Yuan memorialized: \"West of Poqiang, cities are mostly intact and strong and easy to rely on and hold firm.", idiomatic: "Ma Yuan memorialized, \"West of Poqiang, cities are mostly intact and strong and easy to hold.\"" },
  { zh: "其田土肥壤，灌溉流通。", literal: "Its fields and soil are fertile; irrigation flows through.", idiomatic: "Its fields and soil are fertile, and irrigation flows through." },
  { zh: "如令羌在湟中，則為害不休，不可棄也。", literal: "If the Qiang are allowed to remain in Huangzhong, harm will not cease—it cannot be abandoned.", idiomatic: "If the Qiang are allowed to remain in Huangzhong, harm will never cease—it cannot be abandoned.\"" },
  { zh: "」帝從之。", literal: "\" The Emperor followed it.", idiomatic: "The Emperor accepted his advice." },
  { zh: "民歸者三千餘口，援為置長吏，繕城郭，起塢候，開溝洫，勸以耕牧，郡中樂業。", literal: "People who returned numbered more than three thousand mouths; Yuan established chief officials, repaired walls and towers, raised walled watch-posts, opened irrigation ditches, urged farming and herding, and within the commandery all were glad in their occupations.", idiomatic: "More than three thousand people returned; Ma Yuan appointed chief officials, repaired walls and towers, raised walled watch-posts, opened irrigation ditches, urged farming and herding, and the commandery prospered in peace." },
  { zh: "又招撫塞外氏、羌，皆來降附，援奏復其侯王君長，帝悉從之。", literal: "He also recruited and pacified the Di and Qiang beyond the passes; all came to submit and attach themselves; Yuan memorialized to restore their marquis-kings and chieftains, and the Emperor accepted all.", idiomatic: "He also recruited and pacified the Di and Qiang beyond the passes; all came to submit; Ma Yuan memorialized to restore their marquis-kings and chieftains, and the Emperor accepted all." },
  { zh: "乃罷馬成軍。", literal: "He then dismissed Ma Cheng's army.", idiomatic: "He then dismissed Ma Cheng's army." },
  { zh: "11十二月，吳漢自夷陵將三萬人溯江而上，伐公孫述。", literal: "11. Twelfth month: Wu Han from Yiling led thirty thousand men up the Yangzi to attack Gongsun Shu.", idiomatic: "11. In the twelfth month, Wu Han from Yiling led thirty thousand men up the Yangzi to attack Gongsun Shu." },
  { zh: "12郭人及為并州牧，過京師，帝問以得失，人及曰：「選補眾職，當簡天下賢俊，不宜專用南陽人。", literal: "12. Guo Renji became Governor of Bingzhou; passing through the capital, the Emperor asked him about gains and losses; Renji said: \"In selecting and filling all posts one should choose the realm's worthy talent and not exclusively employ men of Nanyang.", idiomatic: "12. Guo Renji became Governor of Bingzhou; passing through the capital, the Emperor asked him about gains and losses; Renji said, \"In selecting and filling all posts one should choose the realm's worthy talent and not exclusively employ men of Nanyang.\"" },
  { zh: "」是時在位多鄉曲故舊，故人及言及之。", literal: "\" At this time those in office were mostly hometown acquaintances and old friends, so Renji's words touched on this.", idiomatic: "At this time those in office were mostly hometown acquaintances and old friends, so Renji's words touched on this." },
  { zh: "<divclass=\"references-small\"><references/></div>", literal: "<divclass=\"references-small\"><references/></div>", idiomatic: "<divclass=\"references-small\"><references/></div>" },
  { zh: "category:資治通鑑", literal: "—", idiomatic: "—" }
];
